class DurationField(Field):
    default_error_messages = {
        'invalid': _('Enter a valid duration.'),
        'overflow': _('The number of days must be between {min_days} and {max_days}.')
    }

    def prepare_value(self, value):
        if isinstance(value, datetime.timedelta):
            return duration_string(value)
        return value

    def to_python(self, value):
        if value in self.empty_values:
            return None
        if isinstance(value, datetime.timedelta):
            return value
        try:
            value = parse_duration(str(value))
        except OverflowError:
            raise ValidationError(self.error_messages['overflow'].format(
                min_days=datetime.timedelta.min.days,
                max_days=datetime.timedelta.max.days,
            ), code='overflow')
        if value is None:
            raise ValidationError(self.error_messages['invalid'], code='invalid')
        return value

class DurationField(Field):
    """
    Store timedelta objects.

    Use interval on PostgreSQL, INTERVAL DAY TO SECOND on Oracle, and bigint
    of microseconds on other databases.
    """
    empty_strings_allowed = False
    default_error_messages = {
        'invalid': _("'%(value)s' value has an invalid format. It must be in "
                     "[DD] [HH:[MM:]]ss[.uuuuuu] format.")
    }
    description = _("Duration")

    def get_internal_type(self):
        return "DurationField"

    def to_python(self, value):
        if value is None:
            return value
        if isinstance(value, datetime.timedelta):
            return value
        try:
            parsed = parse_duration(value)
        except ValueError:
            pass
        else:
            if parsed is not None:
                return parsed

        raise exceptions.ValidationError(
            self.error_messages['invalid'],
            code='invalid',
            params={'value': value},
        )

    def get_db_prep_value(self, value, connection, prepared=False):
        if connection.features.has_native_duration_field:
            return value
        if value is None:
            return None
        return duration_microseconds(value)

    def get_db_converters(self, connection):
        converters = []
        if not connection.features.has_native_duration_field:
            converters.append(connection.ops.convert_durationfield_value)
        return converters + super().get_db_converters(connection)

    def value_to_string(self, obj):
        val = self.value_from_object(obj)
        return '' if val is None else duration_string(val)

    def formfield(self, **kwargs):
        return super().formfield(**{
            'form_class': forms.DurationField,
            **kwargs,
        })

def iter_modules_and_files(modules, extra_files):
    """Iterate through all modules needed to be watched."""
    sys_file_paths = []
    for module in modules:
        # During debugging (with PyDev) the 'typing.io' and 'typing.re' objects
        # are added to sys.modules, however they are types not modules and so
        # cause issues here.
        if not isinstance(module, ModuleType):
            continue
        if module.__name__ == '__main__':
            # __main__ (usually manage.py) doesn't always have a __spec__ set.
            # Handle this by falling back to using __file__, resolved below.
            # See https://docs.python.org/reference/import.html#main-spec
            # __file__ may not exists, e.g. when running ipdb debugger.
            if hasattr(module, '__file__'):
                sys_file_paths.append(module.__file__)
            continue
        if getattr(module, '__spec__', None) is None:
            continue
        spec = module.__spec__
        # Modules could be loaded from places without a concrete location. If
        # this is the case, skip them.
        if spec.has_location:
            origin = spec.loader.archive if isinstance(spec.loader, zipimporter) else spec.origin
            sys_file_paths.append(origin)

    results = set()
    for filename in itertools.chain(sys_file_paths, extra_files):
        if not filename:
            continue
        path = Path(filename)
        try:
            resolved_path = path.resolve(strict=True).absolute()
        except FileNotFoundError:
            # The module could have been removed, don't fail loudly if this
            # is the case.
            continue
        results.add(resolved_path)
    return frozenset(results)

def parse_http_date(date):
    """
    Parse a date format as specified by HTTP RFC7231 section 7.1.1.1.

    The three formats allowed by the RFC are accepted, even if only the first
    one is still in widespread use.

    Return an integer expressed in seconds since the epoch, in UTC.
    """
    # email.utils.parsedate() does the job for RFC1123 dates; unfortunately
    # RFC7231 makes it mandatory to support RFC850 dates too. So we roll
    # our own RFC-compliant parsing.
    for regex in RFC1123_DATE, RFC850_DATE, ASCTIME_DATE:
        m = regex.match(date)
        if m is not None:
            break
    else:
        raise ValueError("%r is not in a valid HTTP date format" % date)
    try:
        year = int(m.group('year'))
        if year < 100:
            if year < 70:
                year += 2000
            else:
                year += 1900
        month = MONTHS.index(m.group('mon').lower()) + 1
        day = int(m.group('day'))
        hour = int(m.group('hour'))
        min = int(m.group('min'))
        sec = int(m.group('sec'))
        result = datetime.datetime(year, month, day, hour, min, sec)
        return calendar.timegm(result.utctimetuple())
    except Exception as exc:
        raise ValueError("%r is not a valid date" % date) from exc

def check_setting_languages(app_configs, **kwargs):
    """Error if LANGUAGES setting is invalid."""
    return [
        Error(E002.msg.format(tag), id=E002.id)
        for tag, _ in settings.LANGUAGES if not isinstance(tag, str) or not language_code_re.match(tag)
    ]

def check_setting_language_code(app_configs, **kwargs):
    """Error if LANGUAGE_CODE setting is invalid."""
    tag = settings.LANGUAGE_CODE
    if not isinstance(tag, str) or not language_code_re.match(tag):
        return [Error(E001.msg.format(tag), id=E001.id)]
    return []

def check_language_settings_consistent(app_configs, **kwargs):
    """Error if language settings are not consistent with each other."""
    available_tags = {i for i, _ in settings.LANGUAGES} | {'en-us'}
    if settings.LANGUAGE_CODE not in available_tags:
        return [E004]
    return []

def delete(self):
    # sort instance collections
    for model, instances in self.data.items():
        self.data[model] = sorted(instances, key=attrgetter("pk"))

    # if possible, bring the models in an order suitable for databases that
    # don't support transactions or cannot defer constraint checks until the
    # end of a transaction.
    self.sort()
    # number of objects deleted for each model label
    deleted_counter = Counter()

    # Optimize for the case with a single obj and no dependencies
    if len(self.data) == 1 and len(instances) == 1:
        instance = list(instances)[0]
        if self.can_fast_delete(instance):
            with transaction.mark_for_rollback_on_error():
                count = sql.DeleteQuery(model).delete_batch([instance.pk], self.using)
            setattr(instance, model._meta.pk.attname, None)
            return count, {model._meta.label: count}

    with transaction.atomic(using=self.using, savepoint=False):
        # send pre_delete signals
        for model, obj in self.instances_with_model():
            if not model._meta.auto_created:
                signals.pre_delete.send(
                    sender=model, instance=obj, using=self.using
                )

        # fast deletes
        for qs in self.fast_deletes:
            count = qs._raw_delete(using=self.using)
            deleted_counter[qs.model._meta.label] += count

        # update fields
        for model, instances_for_fieldvalues in self.field_updates.items():
            for (field, value), instances in instances_for_fieldvalues.items():
                query = sql.UpdateQuery(model)
                query.update_batch([obj.pk for obj in instances],
                                   {field.name: value}, self.using)

        # reverse instance collections
        for instances in self.data.values():
            instances.reverse()

        # delete instances
        for model, instances in self.data.items():
            query = sql.DeleteQuery(model)
            pk_list = [obj.pk for obj in instances]
            count = query.delete_batch(pk_list, self.using)
            deleted_counter[model._meta.label] += count

            if not model._meta.auto_created:
                for obj in instances:
                    signals.post_delete.send(
                        sender=model, instance=obj, using=self.using
                    )

    # update collected instances
    for instances_for_fieldvalues in self.field_updates.values():
        for (field, value), instances in instances_for_fieldvalues.items():
            for obj in instances:
                setattr(obj, field.attname, value)
    for model, instances in self.data.items():
        for instance in instances:
            setattr(instance, model._meta.pk.attname, None)
    return sum(deleted_counter.values()), dict(deleted_counter)

def decode(self, session_data):
    try:
        return signing.loads(session_data, salt=self.key_salt, serializer=self.serializer)
    # RemovedInDjango40Warning: when the deprecation ends, handle here
    # exceptions similar to what _legacy_decode() does now.
    except Exception:
        return self._legacy_decode(session_data)

def _legacy_decode(self, session_data):
    # RemovedInDjango40Warning: pre-Django 3.1 format will be invalid.
    encoded_data = base64.b64decode(session_data.encode('ascii'))
    try:
        # could produce ValueError if there is no ':'
        hash, serialized = encoded_data.split(b':', 1)
        expected_hash = self._hash(serialized)
        if not constant_time_compare(hash.decode(), expected_hash):
            raise SuspiciousSession("Session data corrupted")
        else:
            return self.serializer().loads(serialized)
    except Exception as e:
        # ValueError, SuspiciousOperation, unpickling exceptions. If any of
        # these happen, just return an empty dictionary (an empty session).
        if isinstance(e, SuspiciousOperation):
            logger = logging.getLogger('django.security.%s' % e.__class__.__name__)
            logger.warning(str(e))
        return {}

def execute(self):
    """
    Given the command-line arguments, figure out which subcommand is being
    run, create a parser appropriate to that command, and run it.
    """
    try:
        subcommand = self.argv[1]
    except IndexError:
        subcommand = 'help'  # Display help if no arguments were given.

    # Preprocess options to extract --settings and --pythonpath.
    # These options could affect the commands that are available, so they
    # must be processed early.
    parser = CommandParser(usage='%(prog)s subcommand [options] [args]', add_help=False, allow_abbrev=False)
    parser.add_argument('--settings')
    parser.add_argument('--pythonpath')
    parser.add_argument('args', nargs='*')  # catch-all
    try:
        options, args = parser.parse_known_args(self.argv[2:])
        handle_default_options(options)
    except CommandError:
        pass  # Ignore any option errors at this point.

    try:
        settings.INSTALLED_APPS
    except ImproperlyConfigured as exc:
        self.settings_exception = exc
    except ImportError as exc:
        self.settings_exception = exc

    if settings.configured:
        # Start the auto-reloading dev server even if the code is broken.
        # The hardcoded condition is a code smell but we can't rely on a
        # flag on the command class because we haven't located it yet.
        if subcommand == 'runserver' and '--noreload' not in self.argv:
            try:
                autoreload.check_errors(django.setup)()
            except Exception:
                # The exception will be raised later in the child process
                # started by the autoreloader. Pretend it didn't happen by
                # loading an empty list of applications.
                apps.all_models = defaultdict(dict)
                apps.app_configs = {}
                apps.apps_ready = apps.models_ready = apps.ready = True

                # Remove options not compatible with the built-in runserver
                # (e.g. options for the contrib.staticfiles' runserver).
                # Changes here require manually testing as described in
                # #27522.
                _parser = self.fetch_command('runserver').create_parser('django', 'runserver')
                _options, _args = _parser.parse_known_args(self.argv[2:])
                for _arg in _args:
                    self.argv.remove(_arg)

        # In all other cases, django.setup() is required to succeed.
        else:
            django.setup()

    self.autocomplete()

    if subcommand == 'help':
        if '--commands' in args:
            sys.stdout.write(self.main_help_text(commands_only=True) + '\n')
        elif not options.args:
            sys.stdout.write(self.main_help_text() + '\n')
        else:
            self.fetch_command(options.args[0]).print_help(self.prog_name, options.args[0])
    # Special-cases: We want 'django-admin --version' and
    # 'django-admin --help' to work, for backwards compatibility.
    elif subcommand == 'version' or self.argv[1:] == ['--version']:
        sys.stdout.write(django.get_version() + '\n')
    elif self.argv[1:] in (['--help'], ['-h']):
        sys.stdout.write(self.main_help_text() + '\n')
    else:
        self.fetch_command(subcommand).run_from_argv(self.argv)

def validate(self, value):
    """Validate that the input is in self.choices."""
    super().validate(value)
    if value and not self.valid_value(value):
        raise ValidationError(
            self.error_messages['invalid_choice'],
            code='invalid_choice',
            params={'value': value},
        )

def to_python(self, value):
    if value in self.empty_values:
        return None
    try:
        key = self.to_field_name or 'pk'
        if isinstance(value, self.queryset.model):
            value = getattr(value, key)
        value = self.queryset.get(**{key: value})
    except (ValueError, TypeError, self.queryset.model.DoesNotExist):
        raise ValidationError(self.error_messages['invalid_choice'], code='invalid_choice')
    return value

class AutoFieldMeta(type):
    """
    Metaclass to maintain backward inheritance compatibility for AutoField.

    It is intended that AutoFieldMixin become public API when it is possible to
    create a non-integer automatically-generated field using column defaults
    stored in the database.

    In many areas Django also relies on using isinstance() to check for an
    automatically-generated field as a subclass of AutoField. A new flag needs
    to be implemented on Field to be used instead.

    When these issues have been addressed, this metaclass could be used to
    deprecate inheritance from AutoField and use of isinstance() with AutoField
    for detecting automatically-generated fields.
    """

    @property
    def _subclasses(self):
        return (BigAutoField, SmallAutoField)

    def __instancecheck__(self, instance):
        return isinstance(instance, self._subclasses) or super().__instancecheck__(instance)

    def __subclasscheck__(self, subclass):
        return subclass in self._subclasses or super().__subclasscheck__(subclass)

def __init__(self, initlist=None, error_class=None):
    super().__init__(initlist)

    if error_class is None:
        self.error_class = 'errorlist'
    else:
        self.error_class = 'errorlist {}'.format(error_class)

def get_admin_url(self, remote_field, remote_obj):
    url_name = 'admin:%s_%s_change' % (
        remote_field.model._meta.app_label,
        remote_field.model._meta.model_name,
    )
    try:
        url = reverse(url_name, args=[quote(remote_obj.pk)])
        return format_html('<a href="{}">{}</a>', url, remote_obj)
    except NoReverseMatch:
        return str(remote_obj)

def __init__(self, form, field, is_first, model_admin=None):
    # Make self.field look a little bit like a field. This means that
    # {{ field.name }} must be a useful class name to identify the field.
    # For convenience, store other field-related data here too.
    if callable(field):
        class_name = field.__name__ if field.__name__ != '<lambda>' else ''
    else:
        class_name = field

    if form._meta.labels and class_name in form._meta.labels:
        label = form._meta.labels[class_name]
    else:
        label = label_for_field(field, form._meta.model, model_admin, form=form)

    if form._meta.help_texts and class_name in form._meta.help_texts:
        help_text = form._meta.help_texts[class_name]
    else:
        help_text = help_text_for_field(class_name, form._meta.model)

    if field in form.fields:
        is_hidden = form.fields[field].widget.is_hidden
    else:
        is_hidden = False

    self.field = {
        'name': class_name,
        'label': label,
        'help_text': help_text,
        'field': field,
        'is_hidden': is_hidden,
    }
    self.form = form
    self.model_admin = model_admin
    self.is_first = is_first
    self.is_checkbox = False
    self.is_readonly = True
    self.empty_value_display = model_admin.get_empty_value_display()

def response_add(self, request, obj, post_url_continue=None):
    """
    Determine the HttpResponse for the add_view stage.
    """
    opts = obj._meta
    preserved_filters = self.get_preserved_filters(request)
    obj_url = reverse(
        'admin:%s_%s_change' % (opts.app_label, opts.model_name),
        args=(quote(obj.pk),),
        current_app=self.admin_site.name,
    )
    # Add a link to the object's change form if the user can edit the obj.
    if self.has_change_permission(request, obj):
        obj_repr = format_html('<a href="{}">{}</a>', urlquote(obj_url), obj)
    else:
        obj_repr = str(obj)
    msg_dict = {
        'name': opts.verbose_name,
        'obj': obj_repr,
    }
    # Here, we distinguish between different save types by checking for
    # the presence of keys in request.POST.

    if IS_POPUP_VAR in request.POST:
        to_field = request.POST.get(TO_FIELD_VAR)
        if to_field:
            attr = str(to_field)
        else:
            attr = obj._meta.pk.attname
        value = obj.serializable_value(attr)
        popup_response_data = json.dumps({
            'value': str(value),
            'obj': str(obj),
        })
        return TemplateResponse(request, self.popup_response_template or [
            'admin/%s/%s/popup_response.html' % (opts.app_label, opts.model_name),
            'admin/%s/popup_response.html' % opts.app_label,
            'admin/popup_response.html',
        ], {
            'popup_response_data': popup_response_data,
        })

    elif "_continue" in request.POST or (
            # Redirecting after "Save as new".
            "_saveasnew" in request.POST and self.save_as_continue and
            self.has_change_permission(request, obj)
    ):
        msg = _('The {name} “{obj}” was added successfully.')
        if self.has_change_permission(request, obj):
            msg += ' ' + _('You may edit it again below.')
        self.message_user(request, format_html(msg, **msg_dict), messages.SUCCESS)
        if post_url_continue is None:
            post_url_continue = obj_url
        post_url_continue = add_preserved_filters(
            {'preserved_filters': preserved_filters, 'opts': opts},
            post_url_continue
        )
        return HttpResponseRedirect(post_url_continue)

    elif "_addanother" in request.POST:
        msg = format_html(
            _('The {name} “{obj}” was added successfully. You may add another {name} below.'),
            **msg_dict
        )
        self.message_user(request, msg, messages.SUCCESS)
        redirect_url = request.path
        redirect_url = add_preserved_filters({'preserved_filters': preserved_filters, 'opts': opts}, redirect_url)
        return HttpResponseRedirect(redirect_url)

    else:
        msg = format_html(
            _('The {name} “{obj}” was added successfully.'),
            **msg_dict
        )
        self.message_user(request, msg, messages.SUCCESS)
        return self.response_post_save_add(request, obj)

def __call__(self, value):
    if not isinstance(value, str):
        raise ValidationError(self.message, code=self.code, params={'value': value})
    if self.unsafe_chars.intersection(value):
        raise ValidationError(self.message, code=self.code, params={'value': value})
    # Check if the scheme is valid.
    scheme = value.split('://')[0].lower()
    if scheme not in self.schemes:
        raise ValidationError(self.message, code=self.code, params={'value': value})

    # Then check full URL
    try:
        super().__call__(value)
    except ValidationError as e:
        # Trivial case failed. Try for possible IDN domain
        if value:
            try:
                scheme, netloc, path, query, fragment = urlsplit(value)
            except ValueError:  # for example, "Invalid IPv6 URL"
                raise ValidationError(self.message, code=self.code, params={'value': value})
            try:
                netloc = punycode(netloc)  # IDN -> ACE
            except UnicodeError:  # invalid domain part
                raise e
            url = urlunsplit((scheme, netloc, path, query, fragment))
            super().__call__(url)
        else:
            raise
    else:
        # Now verify IPv6 in the netloc part
        host_match = re.search(r'^\[(.+)\](?::\d{1,5})?$', urlsplit(value).netloc)
        if host_match:
            potential_ip = host_match[1]
            try:
                validate_ipv6_address(potential_ip)
            except ValidationError:
                raise ValidationError(self.message, code=self.code, params={'value': value})

    # The maximum length of a full host name is 253 characters per RFC 1034
    # section 3.1. It's defined to be 255 bytes or less, but this includes
    # one byte for the length of the name and one byte for the trailing dot
    # that's used to indicate absolute names in DNS.
    if len(urlsplit(value).hostname) > 253:
        raise ValidationError(self.message, code=self.code, params={'value': value})

def check_for_template_tags_with_the_same_name(app_configs, **kwargs):
    errors = []
    libraries = defaultdict(list)

    for conf in settings.TEMPLATES:
        custom_libraries = conf.get("OPTIONS", {}).get("libraries", {})
        for module_name, module_path in custom_libraries.items():
            libraries[module_name].append(module_path)

    for module_name, module_path in get_template_tag_modules():
        libraries[module_name].append(module_path)

    for library_name, items in libraries.items():
        if len(items) > 1:
            errors.append(
                Error(
                    E003.msg.format(
                        repr(library_name),
                        ", ".join(repr(item) for item in items),
                    ),
                    id=E003.id,
                )
            )

    return errors

def get_template_tag_modules():
    """
    Yield (module_name, module_path) pairs for all installed template tag
    libraries.
    """
    candidates = ["django.templatetags"]
    candidates.extend(
        f"{app_config.name}.templatetags" for app_config in apps.get_app_configs()
    )

    for candidate in candidates:
        try:
            pkg = import_module(candidate)
        except ImportError:
            # No templatetags package defined. This is safe to ignore.
            continue

        if hasattr(pkg, "__path__"):
            for name in get_package_libraries(pkg):
                yield name[len(candidate) + 1 :], name

def serialize(self):
    enum_class = self.value.__class__
    module = enum_class.__module__
    return (
        "%s.%s[%r]" % (module, enum_class.__qualname__, self.value.name),
        {"import %s" % module},
    )

def _is_expired(self, f):
    """
    Take an open cache file `f` and delete it if it's expired.
    """
    try:
        exp = pickle.load(f)
    except EOFError:
        exp = 0  # An empty file is considered expired.
    if exp is not None and exp < time.time():
        f.close()  # On Windows a file has to be closed before deleting
        self._delete(f.name)
        return True
    return False

def add(self, key, value, timeout=DEFAULT_TIMEOUT, version=None):
    if self.has_key(key, version):
        return False
    self.set(key, value, timeout, version)
    return True

def _check_list_display_item(self, obj, item, label):
    if callable(item):
        return []
    elif hasattr(obj, item):
        return []
    try:
        field = obj.model._meta.get_field(item)
    except FieldDoesNotExist:
        try:
            field = getattr(obj.model, item)
        except AttributeError:
            return [
                checks.Error(
                    "The value of '%s' refers to '%s', which is not a "
                    "callable, an attribute of '%s', or an attribute or "
                    "method on '%s'."
                    % (
                        label,
                        item,
                        obj.__class__.__name__,
                        obj.model._meta.label,
                    ),
                    obj=obj.__class__,
                    id="admin.E108",
                )
            ]
    if isinstance(field, models.ManyToManyField) or (
        getattr(field, "rel", None) and field.rel.field.many_to_one
    ):
        return [
            checks.Error(
                f"The value of '{label}' must not be a many-to-many field or a "
                f"reverse foreign key.",
                obj=obj.__class__,
                id="admin.E109",
            )
        ]
    return []

def label_for_field(name, model, model_admin=None, return_attr=False, form=None):
    """
    Return a sensible label for a field name. The name can be a callable,
    property (but not created with @property decorator), or the name of an
    object's attribute, as well as a model field. If return_attr is True, also
    return the resolved attribute (which could be a callable). This will be
    None if (and only if) the name refers to a field.
    """
    attr = None
    try:
        field = _get_non_gfk_field(model._meta, name)
        try:
            label = field.verbose_name
        except AttributeError:
            # field is likely a ForeignObjectRel
            label = field.related_model._meta.verbose_name
    except FieldDoesNotExist:
        if name == "__str__":
            label = str(model._meta.verbose_name)
            attr = str
        else:
            if callable(name):
                attr = name
            elif hasattr(model_admin, name):
                attr = getattr(model_admin, name)
            elif hasattr(model, name):
                attr = getattr(model, name)
            elif form and name in form.fields:
                attr = form.fields[name]
            else:
                message = "Unable to lookup '%s' on %s" % (
                    name,
                    model._meta.object_name,
                )
                if model_admin:
                    message += " or %s" % model_admin.__class__.__name__
                if form:
                    message += " or %s" % form.__class__.__name__
                raise AttributeError(message)

            if hasattr(attr, "short_description"):
                label = attr.short_description
            elif (
                isinstance(attr, property)
                and hasattr(attr, "fget")
                and hasattr(attr.fget, "short_description")
            ):
                label = attr.fget.short_description
            elif callable(attr):
                if attr.__name__ == "<lambda>":
                    label = "--"
                else:
                    label = pretty_name(attr.__name__)
            else:
                label = pretty_name(name)
    except FieldIsAForeignKeyColumnName:
        label = pretty_name(name)
        attr = name

    if return_attr:
        return (label, attr)
    else:
        return label

def as_sql(self):
    # We don't need quote_name_unless_alias() here, since these are all
    # going to be column names (so we can avoid the extra overhead).
    qn = self.connection.ops.quote_name
    opts = self.query.get_meta()
    insert_statement = self.connection.ops.insert_statement(
        on_conflict=self.query.on_conflict,
    )
    result = ["%s %s" % (insert_statement, qn(opts.db_table))]
    fields = self.query.fields or [opts.pk]
    result.append("(%s)" % ", ".join(qn(f.column) for f in fields))

    if self.query.fields:
        value_rows = [
            [
                self.prepare_value(field, self.pre_save_val(field, obj))
                for field in fields
            ]
            for obj in self.query.objs
        ]
    else:
        # An empty object.
        value_rows = [
            [self.connection.ops.pk_default_value()] for _ in self.query.objs
        ]
        fields = [None]

    # Currently the backends just accept values when generating bulk
    # queries and generate their own placeholders. Doing that isn't
    # necessary and it should be possible to use placeholders and
    # expressions in bulk inserts too.
    can_bulk = (
        not self.returning_fields and self.connection.features.has_bulk_insert
    )

    placeholder_rows, param_rows = self.assemble_as_sql(fields, value_rows)

    on_conflict_suffix_sql = self.connection.ops.on_conflict_suffix_sql(
        fields,
        self.query.on_conflict,
        (f.column for f in self.query.update_fields),
        (f.column for f in self.query.unique_fields),
    )
    if (
        self.returning_fields
        and self.connection.features.can_return_columns_from_insert
    ):
        if self.connection.features.can_return_rows_from_bulk_insert:
            result.append(
                self.connection.ops.bulk_insert_sql(fields, placeholder_rows)
            )
            params = param_rows
        else:
            result.append("VALUES (%s)" % ", ".join(placeholder_rows[0]))
            params = [param_rows[0]]
        if on_conflict_suffix_sql:
            result.append(on_conflict_suffix_sql)
        # Skip empty r_sql to allow subclasses to customize behavior for
        # 3rd party backends. Refs #19096.
        r_sql, self.returning_params = self.connection.ops.return_insert_columns(
            self.returning_fields
        )
        if r_sql:
            result.append(r_sql)
            params += [self.returning_params]
        return [(" ".join(result), tuple(chain.from_iterable(params)))]

    if can_bulk:
        result.append(self.connection.ops.bulk_insert_sql(fields, placeholder_rows))
        if on_conflict_suffix_sql:
            result.append(on_conflict_suffix_sql)
        return [(" ".join(result), tuple(p for ps in param_rows for p in ps))]
    else:
        if on_conflict_suffix_sql:
            result.append(on_conflict_suffix_sql)
        return [
            (" ".join(result + ["VALUES (%s)" % ", ".join(p)]), vals)
            for p, vals in zip(placeholder_rows, param_rows)
        ]

def execute_sql(self, returning_fields=None):
    assert not (
        returning_fields
        and len(self.query.objs) != 1
        and not self.connection.features.can_return_rows_from_bulk_insert
    )
    opts = self.query.get_meta()
    self.returning_fields = returning_fields
    with self.connection.cursor() as cursor:
        for sql, params in self.as_sql():
            cursor.execute(sql, params)
        if not self.returning_fields:
            return []
        if (
            self.connection.features.can_return_rows_from_bulk_insert
            and len(self.query.objs) > 1
        ):
            rows = self.connection.ops.fetch_returned_insert_rows(cursor)
        elif self.connection.features.can_return_columns_from_insert:
            assert len(self.query.objs) == 1
            rows = [
                self.connection.ops.fetch_returned_insert_columns(
                    cursor,
                    self.returning_params,
                )
            ]
        else:
            rows = [
                (
                    self.connection.ops.last_insert_id(
                        cursor,
                        opts.db_table,
                        opts.pk.column,
                    ),
                )
            ]
    cols = [field.get_col(opts.db_table) for field in self.returning_fields]
    converters = self.get_converters(cols)
    if converters:
        rows = list(self.apply_converters(rows, converters))
    return rows

def update_user_library(library):
    """Update style library with user-defined rc files."""
    for stylelib_path in map(os.path.expanduser, USER_LIBRARY_PATHS):
        styles = read_style_directory(stylelib_path)
        update_nested_dict(library, styles)
    return library

def read_style_directory(style_dir):
    """Return dictionary of styles defined in *style_dir*."""
    styles = dict()
    for path in Path(style_dir).glob(f"*.{STYLE_EXTENSION}"):
        with warnings.catch_warnings(record=True) as warns:
            styles[path.stem] = rc_params_from_file(
                path, use_default_template=False)
        for w in warns:
            _log.warning('In %s: %s', path, w.message)
    return styles

def map_diag(self, func, **kwargs):
    """Plot with a univariate function on each diagonal subplot.

    Parameters
    ----------
    func : callable plotting function
        Must take an x array as a positional argument and draw onto the
        "currently active" matplotlib Axes. Also needs to accept kwargs
        called ``color`` and  ``label``.

    """
    # Add special diagonal axes for the univariate plot
    if self.diag_axes is None:
        diag_vars = []
        diag_axes = []
        for i, y_var in enumerate(self.y_vars):
            for j, x_var in enumerate(self.x_vars):
                if x_var == y_var:

                    # Make the density axes
                    diag_vars.append(x_var)
                    ax = self.axes[i, j]
                    diag_ax = ax.twinx()
                    diag_ax.set_axis_off()
                    diag_axes.append(diag_ax)

                    # Work around matplotlib bug
                    # https://github.com/matplotlib/matplotlib/issues/15188
                    if not plt.rcParams.get("ytick.left", True):
                        for tick in ax.yaxis.majorTicks:
                            tick.tick1line.set_visible(False)

                    # Remove main y axis from density axes in a corner plot
                    if self._corner:
                        ax.yaxis.set_visible(False)
                        if self._despine:
                            utils.despine(ax=ax, left=True)
                        # TODO add optional density ticks (on the right)
                        # when drawing a corner plot?

        if self.diag_sharey and diag_axes:
            for ax in diag_axes[1:]:
                share_axis(diag_axes[0], ax, "y")

        self.diag_vars = np.array(diag_vars, np.object_)
        self.diag_axes = np.array(diag_axes, np.object_)

    if "hue" not in signature(func).parameters:
        return self._map_diag_iter_hue(func, **kwargs)

    # Loop over diagonal variables and axes, making one plot in each
    for var, ax in zip(self.diag_vars, self.diag_axes):

        plot_kwargs = kwargs.copy()
        if str(func.__module__).startswith("seaborn"):
            plot_kwargs["ax"] = ax
        else:
            plt.sca(ax)

        vector = self.data[var]
        if self._hue_var is not None:
            hue = self.data[self._hue_var]
        else:
            hue = None

        if self._dropna:
            not_na = vector.notna()
            if hue is not None:
                not_na &= hue.notna()
            vector = vector[not_na]
            if hue is not None:
                hue = hue[not_na]

        plot_kwargs.setdefault("hue", hue)
        plot_kwargs.setdefault("hue_order", self._hue_order)
        plot_kwargs.setdefault("palette", self._orig_palette)
        func(x=vector, **plot_kwargs)
        ax.legend_ = None

    self._add_axis_labels()
    return self

def _find_numeric_cols(self, data):
    """Find which variables in a DataFrame are numeric."""
    numeric_cols = []
    for col in data:
        if variable_type(data[col]) == "numeric":
            numeric_cols.append(col)
    return numeric_cols

def variable_type(vector, boolean_type="numeric"):
    """
    Determine whether a vector contains numeric, categorical, or datetime data.

    This function differs from the pandas typing API in two ways:

    - Python sequences or object-typed PyData objects are considered numeric if
      all of their entries are numeric.
    - String or mixed-type data are considered categorical even if not
      explicitly represented as a :class:`pandas.api.types.CategoricalDtype`.

    Parameters
    ----------
    vector : :func:`pandas.Series`, :func:`numpy.ndarray`, or Python sequence
        Input data to test.
    boolean_type : 'numeric' or 'categorical'
        Type to use for vectors containing only 0s and 1s (and NAs).

    Returns
    -------
    var_type : 'numeric', 'categorical', or 'datetime'
        Name identifying the type of data in the vector.
    """
    vector = pd.Series(vector)

    # If a categorical dtype is set, infer categorical
    if isinstance(vector.dtype, pd.CategoricalDtype):
        return VariableType("categorical")

    # Special-case all-na data, which is always "numeric"
    if pd.isna(vector).all():
        return VariableType("numeric")

    # At this point, drop nans to simplify further type inference
    vector = vector.dropna()

    # Special-case binary/boolean data, allow caller to determine
    # This triggers a numpy warning when vector has strings/objects
    # https://github.com/numpy/numpy/issues/6784
    # Because we reduce with .all(), we are agnostic about whether the
    # comparison returns a scalar or vector, so we will ignore the warning.
    # It triggers a separate DeprecationWarning when the vector has datetimes:
    # https://github.com/numpy/numpy/issues/13548
    # This is considered a bug by numpy and will likely go away.
    with warnings.catch_warnings():
        warnings.simplefilter(
            action='ignore', category=(FutureWarning, DeprecationWarning)
        )
        if np.isin(vector, [0, 1]).all():
            return VariableType(boolean_type)

    # Defer to positive pandas tests
    if pd.api.types.is_numeric_dtype(vector):
        return VariableType("numeric")

    if pd.api.types.is_datetime64_dtype(vector):
        return VariableType("datetime")

    # --- If we get to here, we need to check the entries

    # Check for a collection where everything is a number

    def all_numeric(x):
        for x_i in x:
            if not isinstance(x_i, Number):
                return False
        return True

    if all_numeric(vector):
        return VariableType("numeric")

    # Check for a collection where everything is a datetime

    def all_datetime(x):
        for x_i in x:
            if not isinstance(x_i, (datetime, np.datetime64)):
                return False
        return True

    if all_datetime(vector):
        return VariableType("datetime")

    # Otherwise, our final fallback is to consider things categorical

    return VariableType("categorical")

def map_offdiag(self, func, **kwargs):
    """Plot with a bivariate function on the off-diagonal subplots.

    Parameters
    ----------
    func : callable plotting function
        Must take x, y arrays as positional arguments and draw onto the
        "currently active" matplotlib Axes. Also needs to accept kwargs
        called ``color`` and  ``label``.

    """
    if self.square_grid:
        self.map_lower(func, **kwargs)
        if not self._corner:
            self.map_upper(func, **kwargs)
    else:
        indices = []
        for i, (y_var) in enumerate(self.y_vars):
            for j, (x_var) in enumerate(self.x_vars):
                if x_var != y_var:
                    indices.append((i, j))
        self._map_bivariate(func, indices, **kwargs)
    return self

def merge_data_and_coords(data, coords, compat="broadcast_equals", join="outer"):
    """Used in Dataset.__init__."""
    objects = [data, coords]
    explicit_coords = coords.keys()
    indexes = dict(_extract_indexes_from_coords(coords))
    return merge_core(
        objects, compat, join, explicit_coords=explicit_coords, indexes=indexes
    )

def showfixtures(config):
    from _pytest.main import wrap_session

    return wrap_session(config, _showfixtures_main)

def _showfixtures_main(config, session):
    import _pytest.config

    session.perform_collect()
    curdir = py.path.local()
    tw = _pytest.config.create_terminal_writer(config)
    verbose = config.getvalue("verbose")

    fm = session._fixturemanager

    available = []
    seen = set()

    for argname, fixturedefs in fm._arg2fixturedefs.items():
        assert fixturedefs is not None
        if not fixturedefs:
            continue
        for fixturedef in fixturedefs:
            loc = getlocation(fixturedef.func, curdir)
            if (fixturedef.argname, loc) in seen:
                continue
            seen.add((fixturedef.argname, loc))
            available.append(
                (
                    len(fixturedef.baseid),
                    fixturedef.func.__module__,
                    curdir.bestrelpath(loc),
                    fixturedef.argname,
                    fixturedef,
                )
            )

    available.sort()
    currentmodule = None
    for baseid, module, bestrel, argname, fixturedef in available:
        if currentmodule != module:
            if not module.startswith("_pytest."):
                tw.line()
                tw.sep("-", "fixtures defined from %s" % (module,))
                currentmodule = module
        if verbose <= 0 and argname[0] == "_":
            continue
        if verbose > 0:
            funcargspec = "%s -- %s" % (argname, bestrel)
        else:
            funcargspec = argname
        tw.line(funcargspec, green=True)
        loc = getlocation(fixturedef.func, curdir)
        doc = fixturedef.func.__doc__ or ""
        if doc:
            write_docstring(tw, doc)
        else:
            tw.line("    %s: no docstring available" % (loc,), red=True)

class FixtureDef(object):
    """ A container for a factory definition. """

    def __init__(
        self,
        fixturemanager,
        baseid,
        argname,
        func,
        scope,
        params,
        unittest=False,
        ids=None,
    ):
        self._fixturemanager = fixturemanager
        self.baseid = baseid or ""
        self.has_location = baseid is not None
        self.func = func
        self.argname = argname
        self.scope = scope
        self.scopenum = scope2index(
            scope or "function",
            descr="Fixture '{}'".format(func.__name__),
            where=baseid,
        )
        self.params = params
        self.argnames = getfuncargnames(func, is_method=unittest)
        self.unittest = unittest
        self.ids = ids
        self._finalizers = []

    def addfinalizer(self, finalizer):
        self._finalizers.append(finalizer)

    def finish(self, request):
        exceptions = []
        try:
            while self._finalizers:
                try:
                    func = self._finalizers.pop()
                    func()
                except:  # noqa
                    exceptions.append(sys.exc_info())
            if exceptions:
                e = exceptions[0]
                del (
                    exceptions
                )  # ensure we don't keep all frames alive because of the traceback
                six.reraise(*e)

        finally:
            hook = self._fixturemanager.session.gethookproxy(request.node.fspath)
            hook.pytest_fixture_post_finalizer(fixturedef=self, request=request)
            # even if finalization fails, we invalidate
            # the cached fixture value and remove
            # all finalizers because they may be bound methods which will
            # keep instances alive
            if hasattr(self, "cached_result"):
                del self.cached_result
            self._finalizers = []

    def execute(self, request):
        # get required arguments and register our own finish()
        # with their finalization
        for argname in self.argnames:
            fixturedef = request._get_active_fixturedef(argname)
            if argname != "request":
                fixturedef.addfinalizer(functools.partial(self.finish, request=request))

        my_cache_key = request.param_index
        cached_result = getattr(self, "cached_result", None)
        if cached_result is not None:
            result, cache_key, err = cached_result
            if my_cache_key == cache_key:
                if err is not None:
                    six.reraise(*err)
                else:
                    return result
            # we have a previous but differently parametrized fixture instance
            # so we need to tear it down before creating a new one
            self.finish(request)
            assert not hasattr(self, "cached_result")

        hook = self._fixturemanager.session.gethookproxy(request.node.fspath)
        return hook.pytest_fixture_setup(fixturedef=self, request=request)

    def __repr__(self):
        return "<FixtureDef argname=%r scope=%r baseid=%r>" % (
            self.argname,
            self.scope,
            self.baseid,
        )

def _format_repr_exception(exc: BaseException, obj: Any) -> str:
    try:
        exc_info = _try_repr_or_str(exc)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as exc:
        exc_info = "unpresentable exception ({})".format(_try_repr_or_str(exc))
    return "<[{} raised in repr()] {} object at 0x{:x}>".format(
        exc_info, obj.__class__.__name__, id(obj)
    )

def repr(self, x: Any) -> str:
    try:
        s = super().repr(x)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as exc:
        s = _format_repr_exception(exc, x)
    return _ellipsize(s, self.maxsize)

def repr_instance(self, x: Any, level: int) -> str:
    try:
        s = repr(x)
    except (KeyboardInterrupt, SystemExit):
        raise
    except BaseException as exc:
        s = _format_repr_exception(exc, x)
    return _ellipsize(s, self.maxsize)

def pytest_runtest_setup(item: Item) -> None:
    skipped = evaluate_skip_marks(item)
    if skipped:
        raise skip.Exception(skipped.reason, _use_item_location=True)

    item._store[xfailed_key] = xfailed = evaluate_xfail_marks(item)
    if xfailed and not item.config.option.runxfail and not xfailed.run:
        xfail("[NOTRUN] " + xfailed.reason)

def _importtestmodule(self):
    # We assume we are only called once per module.
    importmode = self.config.getoption("--import-mode")
    try:
        mod = import_path(self.path, mode=importmode, root=self.config.rootpath)
    except SyntaxError as e:
        raise self.CollectError(
            ExceptionInfo.from_current().getrepr(style="short")
        ) from e
    except ImportPathMismatchError as e:
        raise self.CollectError(
            "import file mismatch:\n"
            "imported module %r has this __file__ attribute:\n"
            "  %s\n"
            "which is not the same as the test file we want to collect:\n"
            "  %s\n"
            "HINT: remove __pycache__ / .pyc files and/or use a "
            "unique basename for your test file modules" % e.args
        ) from e
    except ImportError as e:
        exc_info = ExceptionInfo.from_current()
        if self.config.getoption("verbose") < 2:
            exc_info.traceback = exc_info.traceback.filter(filter_traceback)
        exc_repr = (
            exc_info.getrepr(style="short")
            if exc_info.traceback
            else exc_info.exconly()
        )
        formatted_tb = str(exc_repr)
        raise self.CollectError(
            "ImportError while importing test module '{path}'.\n"
            "Hint: make sure your test modules/packages have valid Python names.\n"
            "Traceback:\n"
            "{traceback}".format(path=self.path, traceback=formatted_tb)
        ) from e
    except skip.Exception as e:
        if e.allow_module_level:
            raise
        raise self.CollectError(
            "Using pytest.skip outside of a test is not allowed. "
            "To decorate a test function, use the @pytest.mark.skip "
            "or @pytest.mark.skipif decorators instead, and to skip a "
            "module use `pytestmark = pytest.mark.{skip,skipif}."
        ) from e
    self.config.pluginmanager.consider_module(mod)
    return mod

def inherited_members_option(arg: Any) -> Union[object, Set[str]]:
    """Used to convert the :members: option to auto directives."""
    if arg in (None, True):
        return 'object'
    else:
        return arg

def is_filtered_inherited_member(name: str, obj: Any) -> bool:
    if inspect.isclass(self.object):
        for cls in self.object.__mro__:
            if cls.__name__ == self.options.inherited_members and cls != self.object:
                # given member is a member of specified *super class*
                return True
            elif name in cls.__dict__:
                return False
            elif name in self.get_attr(cls, '__annotations__', {}):
                return False
            elif isinstance(obj, ObjectMember) and obj.class_ is cls:
                return False

    return False

class ClassDocumenter(DocstringSignatureMixin, ModuleLevelDocumenter):  # type: ignore
    """
    Specialized Documenter subclass for classes.
    """
    objtype = 'class'
    member_order = 20
    option_spec: OptionSpec = {
        'members': members_option, 'undoc-members': bool_option,
        'noindex': bool_option, 'inherited-members': inherited_members_option,
        'show-inheritance': bool_option, 'member-order': member_order_option,
        'exclude-members': exclude_members_option,
        'private-members': members_option, 'special-members': members_option,
        'class-doc-from': class_doc_from_option,
    }

    _signature_class: Any = None
    _signature_method_name: str = None

    def __init__(self, *args: Any) -> None:
        super().__init__(*args)

        if self.config.autodoc_class_signature == 'separated':
            self.options = self.options.copy()

            # show __init__() method
            if self.options.special_members is None:
                self.options['special-members'] = ['__new__', '__init__']
            else:
                self.options.special_members.append('__new__')
                self.options.special_members.append('__init__')

        merge_members_option(self.options)

    @classmethod
    def can_document_member(cls, member: Any, membername: str, isattr: bool, parent: Any
                            ) -> bool:
        return isinstance(member, type)

    def import_object(self, raiseerror: bool = False) -> bool:
        ret = super().import_object(raiseerror)
        # if the class is documented under another name, document it
        # as data/attribute
        if ret:
            if hasattr(self.object, '__name__'):
                self.doc_as_attr = (self.objpath[-1] != self.object.__name__)
            else:
                self.doc_as_attr = True
        return ret

    def _get_signature(self) -> Tuple[Optional[Any], Optional[str], Optional[Signature]]:
        def get_user_defined_function_or_method(obj: Any, attr: str) -> Any:
            """ Get the `attr` function or method from `obj`, if it is user-defined. """
            if inspect.is_builtin_class_method(obj, attr):
                return None
            attr = self.get_attr(obj, attr, None)
            if not (inspect.ismethod(attr) or inspect.isfunction(attr)):
                return None
            return attr

        # This sequence is copied from inspect._signature_from_callable.
        # ValueError means that no signature could be found, so we keep going.

        # First, we check the obj has a __signature__ attribute
        if (hasattr(self.object, '__signature__') and
                isinstance(self.object.__signature__, Signature)):
            return None, None, self.object.__signature__

        # Next, let's see if it has an overloaded __call__ defined
        # in its metaclass
        call = get_user_defined_function_or_method(type(self.object), '__call__')

        if call is not None:
            if "{0.__module__}.{0.__qualname__}".format(call) in _METACLASS_CALL_BLACKLIST:
                call = None

        if call is not None:
            self.env.app.emit('autodoc-before-process-signature', call, True)
            try:
                sig = inspect.signature(call, bound_method=True,
                                        type_aliases=self.config.autodoc_type_aliases)
                return type(self.object), '__call__', sig
            except ValueError:
                pass

        # Now we check if the 'obj' class has a '__new__' method
        new = get_user_defined_function_or_method(self.object, '__new__')

        if new is not None:
            if "{0.__module__}.{0.__qualname__}".format(new) in _CLASS_NEW_BLACKLIST:
                new = None

        if new is not None:
            self.env.app.emit('autodoc-before-process-signature', new, True)
            try:
                sig = inspect.signature(new, bound_method=True,
                                        type_aliases=self.config.autodoc_type_aliases)
                return self.object, '__new__', sig
            except ValueError:
                pass

        # Finally, we should have at least __init__ implemented
        init = get_user_defined_function_or_method(self.object, '__init__')
        if init is not None:
            self.env.app.emit('autodoc-before-process-signature', init, True)
            try:
                sig = inspect.signature(init, bound_method=True,
                                        type_aliases=self.config.autodoc_type_aliases)
                return self.object, '__init__', sig
            except ValueError:
                pass

        # None of the attributes are user-defined, so fall back to let inspect
        # handle it.
        # We don't know the exact method that inspect.signature will read
        # the signature from, so just pass the object itself to our hook.
        self.env.app.emit('autodoc-before-process-signature', self.object, False)
        try:
            sig = inspect.signature(self.object, bound_method=False,
                                    type_aliases=self.config.autodoc_type_aliases)
            return None, None, sig
        except ValueError:
            pass

        # Still no signature: happens e.g. for old-style classes
        # with __init__ in C and no `__text_signature__`.
        return None, None, None

    def format_args(self, **kwargs: Any) -> str:
        if self.config.autodoc_typehints in ('none', 'description'):
            kwargs.setdefault('show_annotation', False)
        if self.config.autodoc_typehints_format == "short":
            kwargs.setdefault('unqualified_typehints', True)

        try:
            self._signature_class, self._signature_method_name, sig = self._get_signature()
        except TypeError as exc:
            # __signature__ attribute contained junk
            logger.warning(__("Failed to get a constructor signature for %s: %s"),
                           self.fullname, exc)
            return None

        if sig is None:
            return None

        return stringify_signature(sig, show_return_annotation=False, **kwargs)

    def _find_signature(self) -> Tuple[str, str]:
        result = super()._find_signature()
        if result is not None:
            # Strip a return value from signature of constructor in docstring (first entry)
            result = (result[0], None)

        for i, sig in enumerate(self._signatures):
            if sig.endswith(' -> None'):
                # Strip a return value from signatures of constructor in docstring (subsequent
                # entries)
                self._signatures[i] = sig[:-8]

        return result

    def format_signature(self, **kwargs: Any) -> str:
        if self.doc_as_attr:
            return ''
        if self.config.autodoc_class_signature == 'separated':
            # do not show signatures
            return ''

        if self.config.autodoc_typehints_format == "short":
            kwargs.setdefault('unqualified_typehints', True)

        sig = super().format_signature()
        sigs = []

        overloads = self.get_overloaded_signatures()
        if overloads and self.config.autodoc_typehints != 'none':
            # Use signatures for overloaded methods instead of the implementation method.
            method = safe_getattr(self._signature_class, self._signature_method_name, None)
            __globals__ = safe_getattr(method, '__globals__', {})
            for overload in overloads:
                overload = evaluate_signature(overload, __globals__,
                                              self.config.autodoc_type_aliases)

                parameters = list(overload.parameters.values())
                overload = overload.replace(parameters=parameters[1:],
                                            return_annotation=Parameter.empty)
                sig = stringify_signature(overload, **kwargs)
                sigs.append(sig)
        else:
            sigs.append(sig)

        return "\n".join(sigs)

    def get_overloaded_signatures(self) -> List[Signature]:
        if self._signature_class and self._signature_method_name:
            for cls in self._signature_class.__mro__:
                try:
                    analyzer = ModuleAnalyzer.for_module(cls.__module__)
                    analyzer.analyze()
                    qualname = '.'.join([cls.__qualname__, self._signature_method_name])
                    if qualname in analyzer.overloads:
                        return analyzer.overloads.get(qualname)
                    elif qualname in analyzer.tagorder:
                        # the constructor is defined in the class, but not overridden.
                        return []
                except PycodeError:
                    pass

        return []

    def get_canonical_fullname(self) -> Optional[str]:
        __modname__ = safe_getattr(self.object, '__module__', self.modname)
        __qualname__ = safe_getattr(self.object, '__qualname__', None)
        if __qualname__ is None:
            __qualname__ = safe_getattr(self.object, '__name__', None)
        if __qualname__ and '<locals>' in __qualname__:
            # No valid qualname found if the object is defined as locals
            __qualname__ = None

        if __modname__ and __qualname__:
            return '.'.join([__modname__, __qualname__])
        else:
            return None

    def add_directive_header(self, sig: str) -> None:
        sourcename = self.get_sourcename()

        if self.doc_as_attr:
            self.directivetype = 'attribute'
        super().add_directive_header(sig)

        if self.analyzer and '.'.join(self.objpath) in self.analyzer.finals:
            self.add_line('   :final:', sourcename)

        canonical_fullname = self.get_canonical_fullname()
        if not self.doc_as_attr and canonical_fullname and self.fullname != canonical_fullname:
            self.add_line('   :canonical: %s' % canonical_fullname, sourcename)

        # add inheritance info, if wanted
        if not self.doc_as_attr and self.options.show_inheritance:
            if inspect.getorigbases(self.object):
                # A subclass of generic types
                # refs: PEP-560 <https://peps.python.org/pep-0560/>
                bases = list(self.object.__orig_bases__)
            elif hasattr(self.object, '__bases__') and len(self.object.__bases__):
                # A normal class
                bases = list(self.object.__bases__)
            else:
                bases = []

            self.env.events.emit('autodoc-process-bases',
                                 self.fullname, self.object, self.options, bases)

            if self.config.autodoc_typehints_format == "short":
                base_classes = [restify(cls, "smart") for cls in bases]
            else:
                base_classes = [restify(cls) for cls in bases]

            sourcename = self.get_sourcename()
            self.add_line('', sourcename)
            self.add_line('   ' + _('Bases: %s') % ', '.join(base_classes), sourcename)

    def get_object_members(self, want_all: bool) -> Tuple[bool, ObjectMembers]:
        members = get_class_members(self.object, self.objpath, self.get_attr)
        if not want_all:
            if not self.options.members:
                return False, []  # type: ignore
            # specific members given
            selected = []
            for name in self.options.members:  # type: str
                if name in members:
                    selected.append(members[name])
                else:
                    logger.warning(__('missing attribute %s in object %s') %
                                   (name, self.fullname), type='autodoc')
            return False, selected
        elif self.options.inherited_members:
            return False, list(members.values())
        else:
            return False, [m for m in members.values() if m.class_ == self.object]

    def get_doc(self, ignore: int = None) -> Optional[List[List[str]]]:
        if self.doc_as_attr:
            # Don't show the docstring of the class when it is an alias.
            comment = self.get_variable_comment()
            if comment:
                return []
            else:
                return None

        lines = getattr(self, '_new_docstrings', None)
        if lines is not None:
            return lines

        classdoc_from = self.options.get('class-doc-from', self.config.autoclass_content)

        docstrings = []
        attrdocstring = getdoc(self.object, self.get_attr)
        if attrdocstring:
            docstrings.append(attrdocstring)

        # for classes, what the "docstring" is can be controlled via a
        # config value; the default is only the class docstring
        if classdoc_from in ('both', 'init'):
            __init__ = self.get_attr(self.object, '__init__', None)
            initdocstring = getdoc(__init__, self.get_attr,
                                   self.config.autodoc_inherit_docstrings,
                                   self.object, '__init__')
            # for new-style classes, no __init__ means default __init__
            if (initdocstring is not None and
                (initdocstring == object.__init__.__doc__ or  # for pypy
                 initdocstring.strip() == object.__init__.__doc__)):  # for !pypy
                initdocstring = None
            if not initdocstring:
                # try __new__
                __new__ = self.get_attr(self.object, '__new__', None)
                initdocstring = getdoc(__new__, self.get_attr,
                                       self.config.autodoc_inherit_docstrings,
                                       self.object, '__new__')
                # for new-style classes, no __new__ means default __new__
                if (initdocstring is not None and
                    (initdocstring == object.__new__.__doc__ or  # for pypy
                     initdocstring.strip() == object.__new__.__doc__)):  # for !pypy
                    initdocstring = None
            if initdocstring:
                if classdoc_from == 'init':
                    docstrings = [initdocstring]
                else:
                    docstrings.append(initdocstring)

        tab_width = self.directive.state.document.settings.tab_width
        return [prepare_docstring(docstring, ignore, tab_width) for docstring in docstrings]

    def get_variable_comment(self) -> Optional[List[str]]:
        try:
            key = ('', '.'.join(self.objpath))
            if self.doc_as_attr:
                analyzer = ModuleAnalyzer.for_module(self.modname)
            else:
                analyzer = ModuleAnalyzer.for_module(self.get_real_modname())
            analyzer.analyze()
            return list(analyzer.attr_docs.get(key, []))
        except PycodeError:
            return None

    def add_content(self, more_content: Optional[StringList], no_docstring: bool = False
                    ) -> None:
        if self.doc_as_attr and self.modname != self.get_real_modname():
            try:
                # override analyzer to obtain doccomment around its definition.
                self.analyzer = ModuleAnalyzer.for_module(self.modname)
                self.analyzer.analyze()
            except PycodeError:
                pass

        if self.doc_as_attr and not self.get_variable_comment():
            try:
                if self.config.autodoc_typehints_format == "short":
                    alias = restify(self.object, "smart")
                else:
                    alias = restify(self.object)
                more_content = StringList([_('alias of %s') % alias], source='')
            except AttributeError:
                pass  # Invalid class object is passed.

        super().add_content(more_content)

    def document_members(self, all_members: bool = False) -> None:
        if self.doc_as_attr:
            return
        super().document_members(all_members)

    def generate(self, more_content: Optional[StringList] = None, real_modname: str = None,
                 check_module: bool = False, all_members: bool = False) -> None:
        # Do not pass real_modname and use the name from the __module__
        # attribute of the class.
        # If a class gets imported into the module real_modname
        # the analyzer won't find the source of the class, if
        # it looks in real_modname.
        return super().generate(more_content=more_content,
                                check_module=check_module,
                                all_members=all_members)

def filter_members(self, members: ObjectMembers, want_all: bool
                   ) -> List[Tuple[str, Any, bool]]:
    """Filter the given member list.

    Members are skipped if

    - they are private (except if given explicitly or the private-members
      option is set)
    - they are special methods (except if given explicitly or the
      special-members option is set)
    - they are undocumented (except if the undoc-members option is set)

    The user can override the skipping decision by connecting to the
    ``autodoc-skip-member`` event.
    """
    def is_filtered_inherited_member(name: str, obj: Any) -> bool:
        if inspect.isclass(self.object):
            for cls in self.object.__mro__:
                if cls.__name__ == self.options.inherited_members and cls != self.object:
                    # given member is a member of specified *super class*
                    return True
                elif name in cls.__dict__:
                    return False
                elif name in self.get_attr(cls, '__annotations__', {}):
                    return False
                elif isinstance(obj, ObjectMember) and obj.class_ is cls:
                    return False

        return False

    ret = []

    # search for members in source code too
    namespace = '.'.join(self.objpath)  # will be empty for modules

    if self.analyzer:
        attr_docs = self.analyzer.find_attr_docs()
    else:
        attr_docs = {}

    # process members and determine which to skip
    for obj in members:
        try:
            membername, member = obj
            # if isattr is True, the member is documented as an attribute
            if member is INSTANCEATTR:
                isattr = True
            elif (namespace, membername) in attr_docs:
                isattr = True
            else:
                isattr = False

            doc = getdoc(member, self.get_attr, self.config.autodoc_inherit_docstrings,
                         self.object, membername)
            if not isinstance(doc, str):
                # Ignore non-string __doc__
                doc = None

            # if the member __doc__ is the same as self's __doc__, it's just
            # inherited and therefore not the member's doc
            cls = self.get_attr(member, '__class__', None)
            if cls:
                cls_doc = self.get_attr(cls, '__doc__', None)
                if cls_doc == doc:
                    doc = None

            if isinstance(obj, ObjectMember) and obj.docstring:
                # hack for ClassDocumenter to inject docstring via ObjectMember
                doc = obj.docstring

            doc, metadata = separate_metadata(doc)
            has_doc = bool(doc)

            if 'private' in metadata:
                # consider a member private if docstring has "private" metadata
                isprivate = True
            elif 'public' in metadata:
                # consider a member public if docstring has "public" metadata
                isprivate = False
            else:
                isprivate = membername.startswith('_')

            keep = False
            if ismock(member) and (namespace, membername) not in attr_docs:
                # mocked module or object
                pass
            elif (self.options.exclude_members and
                  membername in self.options.exclude_members):
                # remove members given by exclude-members
                keep = False
            elif want_all and special_member_re.match(membername):
                # special __methods__
                if (self.options.special_members and
                        membername in self.options.special_members):
                    if membername == '__doc__':
                        keep = False
                    elif is_filtered_inherited_member(membername, obj):
                        keep = False
                    else:
                        keep = has_doc or self.options.undoc_members
                else:
                    keep = False
            elif (namespace, membername) in attr_docs:
                if want_all and isprivate:
                    if self.options.private_members is None:
                        keep = False
                    else:
                        keep = membername in self.options.private_members
                else:
                    # keep documented attributes
                    keep = True
            elif want_all and isprivate:
                if has_doc or self.options.undoc_members:
                    if self.options.private_members is None:
                        keep = False
                    elif is_filtered_inherited_member(membername, obj):
                        keep = False
                    else:
                        keep = membername in self.options.private_members
                else:
                    keep = False
            else:
                if (self.options.members is ALL and
                        is_filtered_inherited_member(membername, obj)):
                    keep = False
                else:
                    # ignore undocumented members if :undoc-members: is not given
                    keep = has_doc or self.options.undoc_members

            if isinstance(obj, ObjectMember) and obj.skipped:
                # forcedly skipped member (ex. a module attribute not defined in __all__)
                keep = False

            # give the user a chance to decide whether this member
            # should be skipped
            if self.env.app:
                # let extensions preprocess docstrings
                skip_user = self.env.app.emit_firstresult(
                    'autodoc-skip-member', self.objtype, membername, member,
                    not keep, self.options)
                if skip_user is not None:
                    keep = not skip_user
        except Exception as exc:
            logger.warning(__('autodoc: failed to determine %s.%s (%r) to be documented, '
                              'the following exception was raised:\n%s'),
                           self.name, membername, member, exc, type='autodoc')
            keep = False

        if keep:
            ret.append((membername, member, isattr))

    return ret

def get_target_uri(self, docname: str, typ: str = None) -> str:
    if typ == 'token':
        return ''
    raise NoUri(docname, typ)

def init(self) -> None:
    if not self.config.man_pages:
        logger.warning(__('no "man_pages" config value found; no manual pages '
                          'will be written'))

def _parse_parameters_section(self, section: str) -> List[str]:
    if self._config.napoleon_use_param:
        # Allow to declare multiple parameters at once (ex: x, y: int)
        fields = self._consume_fields(multiple=True)
        return self._format_docutils_params(fields)
    else:
        fields = self._consume_fields()
        return self._format_fields(_('Parameters'), fields)

class MCodePrinter(CodePrinter):
    """A printer to convert python expressions to
    strings of the Wolfram's Mathematica code
    """
    printmethod = "_mcode"

    _default_settings = {
        'order': None,
        'full_prec': 'auto',
        'precision': 15,
        'user_functions': {},
        'human': True,
    }

    _number_symbols = set()
    _not_supported = set()

    def __init__(self, settings={}):
        """Register function mappings supplied by user"""
        CodePrinter.__init__(self, settings)
        self.known_functions = dict(known_functions)
        userfuncs = settings.get('user_functions', {})
        for k, v in userfuncs.items():
            if not isinstance(v, list):
                userfuncs[k] = [(lambda *x: True, v)]
                self.known_functions.update(userfuncs)

    doprint = StrPrinter.doprint

    def _print_Pow(self, expr):
        PREC = precedence(expr)
        return '%s^%s' % (self.parenthesize(expr.base, PREC),
                          self.parenthesize(expr.exp, PREC))

    def _print_Mul(self, expr):
        PREC = precedence(expr)
        c, nc = expr.args_cnc()
        res = super(MCodePrinter, self)._print_Mul(expr.func(*c))
        if nc:
            res += '*'
            res += '**'.join(self.parenthesize(a, PREC) for a in nc)
        return res

    def _print_Pi(self, expr):
        return 'Pi'

    def _print_Infinity(self, expr):
        return 'Infinity'

    def _print_NegativeInfinity(self, expr):
        return '-Infinity'

    def _print_list(self, expr):
        return '{' + ', '.join(self.doprint(a) for a in expr) + '}'
    _print_tuple = _print_list
    _print_Tuple = _print_list

    def _print_Function(self, expr):
        if expr.func.__name__ in self.known_functions:
            cond_mfunc = self.known_functions[expr.func.__name__]
            for cond, mfunc in cond_mfunc:
                if cond(*expr.args):
                    return "%s[%s]" % (mfunc, self.stringify(expr.args, ", "))
        return expr.func.__name__ + "[%s]" % self.stringify(expr.args, ", ")

    def _print_Integral(self, expr):
        if len(expr.variables) == 1 and not expr.limits[0][1:]:
            args = [expr.args[0], expr.variables[0]]
        else:
            args = expr.args
        return "Hold[Integrate[" + ', '.join(self.doprint(a) for a in args) + "]]"

    def _print_Sum(self, expr):
        return "Hold[Sum[" + ', '.join(self.doprint(a) for a in expr.args) + "]]"

def eval(cls, arg):
    from sympy import cot
    arg = sympify(arg)

    if arg.is_Number:
        if arg is S.NaN:
            return S.NaN
        elif arg is S.Infinity:
            return S.One
        elif arg is S.NegativeInfinity:
            return S.NegativeOne
        elif arg is S.Zero:
            return S.ComplexInfinity
        elif arg.is_negative:
            return -cls(-arg)
    else:
        if arg is S.ComplexInfinity:
            return S.NaN

        i_coeff = arg.as_coefficient(S.ImaginaryUnit)

        if i_coeff is not None:
            if _coeff_isneg(i_coeff):
                return S.ImaginaryUnit * cot(-i_coeff)
            return -S.ImaginaryUnit * cot(i_coeff)
        else:
            if _coeff_isneg(arg):
                return -cls(-arg)

        if arg.is_Add:
            x, m = _peeloff_ipi(arg)
            if m:
                cothm = coth(m)
                if cotm is S.ComplexInfinity:
                    return coth(x)
                else: # cothm == 0
                    return tanh(x)

        if arg.func == asinh:
            x = arg.args[0]
            return sqrt(1 + x**2)/x

        if arg.func == acosh:
            x = arg.args[0]
            return x/(sqrt(x - 1) * sqrt(x + 1))

        if arg.func == atanh:
            return 1/arg.args[0]

        if arg.func == acoth:
            return arg.args[0]

def _hprint_Function(self, func):
    r'''
    Logic to decide how to render a function to latex
      - if it is a recognized latex name, use the appropriate latex command
      - if it is a single letter, just use that letter
      - if it is a longer name, then put \operatorname{} around it and be
        mindful of undercores in the name
    '''
    func = self._deal_with_super_sub(func)
    if func in accepted_latex_functions:
        name = r"\%s" % func
    elif len(func) == 1 or func.startswith('\\'):
        name = func
    else:
        name = r"\operatorname{%s}" % func
    return name

def _print_Function(self, expr, exp=None):
    r'''
    Render functions to LaTeX, handling functions that LaTeX knows about
    e.g., sin, cos, ... by using the proper LaTeX command (\sin, \cos, ...).
    For single-letter function names, render them as regular LaTeX math
    symbols. For multi-letter function names that LaTeX does not know
    about, (e.g., Li, sech) use \operatorname{} so that the function name
    is rendered in Roman font and LaTeX handles spacing properly.

    expr is the expression involving the function
    exp is an exponent
    '''
    func = expr.func.__name__
    if hasattr(self, '_print_' + func) and \
        not isinstance(expr.func, UndefinedFunction):
        return getattr(self, '_print_' + func)(expr, exp)
    else:
        args = [ str(self._print(arg)) for arg in expr.args ]
        # How inverse trig functions should be displayed, formats are:
        # abbreviated: asin, full: arcsin, power: sin^-1
        inv_trig_style = self._settings['inv_trig_style']
        # If we are dealing with a power-style inverse trig function
        inv_trig_power_case = False
        # If it is applicable to fold the argument brackets
        can_fold_brackets = self._settings['fold_func_brackets'] and \
            len(args) == 1 and \
            not self._needs_function_brackets(expr.args[0])

        inv_trig_table = ["asin", "acos", "atan", "acot"]

        # If the function is an inverse trig function, handle the style
        if func in inv_trig_table:
            if inv_trig_style == "abbreviated":
                func = func
            elif inv_trig_style == "full":
                func = "arc" + func[1:]
            elif inv_trig_style == "power":
                func = func[1:]
                inv_trig_power_case = True

                # Can never fold brackets if we're raised to a power
                if exp is not None:
                    can_fold_brackets = False

        if inv_trig_power_case:
            if func in accepted_latex_functions:
                name = r"\%s^{-1}" % func
            else:
                name = r"\operatorname{%s}^{-1}" % func
        elif exp is not None:
            name = r'%s^{%s}' % (self._hprint_Function(func), exp)
        else:
            name = self._hprint_Function(func)

        if can_fold_brackets:
            if func in accepted_latex_functions:
                # Wrap argument safely to avoid parse-time conflicts
                # with the function name itself
                name += r" {%s}"
            else:
                name += r"%s"
        else:
            name += r"{\left (%s \right )}"

        if inv_trig_power_case and exp is not None:
            name += r"^{%s}" % exp

        return name % ",".join(args)

def _is_safe_ident(cls, ident):
    return isinstance(ident, str) and ident.isidentifier() \
            and not keyword.iskeyword(ident)

def _print_Add(self, expr, order=None):
    if self.order == 'none':
        terms = list(expr.args)
    else:
        terms = self._as_ordered_terms(expr, order=order)
    pforms, indices = [], []

    def pretty_negative(pform, index):
        """Prepend a minus sign to a pretty form. """
        #TODO: Move this code to prettyForm
        if index == 0:
            if pform.height() > 1:
                pform_neg = '- '
            else:
                pform_neg = '-'
        else:
            pform_neg = ' - '

        if (pform.binding > prettyForm.NEG
            or pform.binding == prettyForm.ADD):
            p = stringPict(*pform.parens())
        else:
            p = pform
        p = stringPict.next(pform_neg, p)
        # Lower the binding to NEG, even if it was higher. Otherwise, it
        # will print as a + ( - (b)), instead of a - (b).
        return prettyForm(binding=prettyForm.NEG, *p)

    for i, term in enumerate(terms):
        if term.is_Mul and _coeff_isneg(term):
            coeff, other = term.as_coeff_mul(rational=False)
            pform = self._print(Mul(-coeff, *other, evaluate=False))
            pforms.append(pretty_negative(pform, i))
        elif term.is_Rational and term.q > 1:
            pforms.append(None)
            indices.append(i)
        elif term.is_Number and term < 0:
            pform = self._print(-term)
            pforms.append(pretty_negative(pform, i))
        elif term.is_Relational:
            pforms.append(prettyForm(*self._print(term).parens()))
        else:
            pforms.append(self._print(term))

    if indices:
        large = True

        for pform in pforms:
            if pform is not None and pform.height() > 1:
                break
        else:
            large = False

        for i in indices:
            term, negative = terms[i], False

            if term < 0:
                term, negative = -term, True

            if large:
                pform = prettyForm(str(term.p))/prettyForm(str(term.q))
            else:
                pform = self._print(term)

            if negative:
                pform = pretty_negative(pform, i)

            pforms[i] = pform

    return prettyForm.__add__(*pforms)

def __add__(self, *others):
    """Make a pretty addition.
    Addition of negative numbers is simplified.
    """
    arg = self
    if arg.binding > prettyForm.NEG:
        arg = stringPict(*arg.parens())
    result = [arg]
    for arg in others:
        #add parentheses for weak binders
        if arg.binding > prettyForm.NEG:
            arg = stringPict(*arg.parens())
        #use existing minus sign if available
        if arg.binding != prettyForm.NEG:
            result.append(' + ')
        result.append(arg)
    return prettyForm(binding=prettyForm.ADD, *stringPict.next(*result))

def __eq__(self, other):
    try:
        other = sympify(other)
        if not isinstance(other, Expr):
            return False
    except (SympifyError, SyntaxError):
        return False
    # check for pure number expr
    if  not (self.is_Number and other.is_Number) and (
            type(self) != type(other)):
        return False
    a, b = self._hashable_content(), other._hashable_content()
    if a != b:
        return False
    # check number *in* an expression
    for a, b in zip(a, b):
        if not isinstance(a, Expr):
            continue
        if a.is_Number and type(a) != type(b):
            return False
    return True

def _entry(self, i, j, **kwargs):
    # Find row entry
    for row_block, numrows in enumerate(self.rowblocksizes):
        if (i < numrows) != False:
            break
        else:
            i -= numrows
    for col_block, numcols in enumerate(self.colblocksizes):
        if (j < numcols) != False:
            break
        else:
            j -= numcols
    return self.blocks[row_block, col_block][i, j]

def _print_ExpBase(self, e):
    # TODO should exp_polar be printed differently?
    #      what about exp_polar(0), exp_polar(1)?
    base = prettyForm(pretty_atom('Exp1', 'e'))
    return base ** self._print(e.args[0])

def _print_Pow(self, power):
    from sympy.simplify.simplify import fraction
    b, e = power.as_base_exp()
    if power.is_commutative:
        if e is S.NegativeOne:
            return prettyForm("1")/self._print(b)
        n, d = fraction(e)
        if n is S.One and d.is_Atom and not e.is_Integer and self._settings['root_notation']:
            return self._print_nth_root(b, e)
        if e.is_Rational and e < 0:
            return prettyForm("1")/self._print(Pow(b, -e, evaluate=False))

    if b.is_Relational:
        return prettyForm(*self._print(b).parens()).__pow__(self._print(e))

    return self._print(b)**self._print(e)

def _eval_expand_tensorproduct(self, **hints):
    """Distribute TensorProducts across addition."""
    args = self.args
    add_args = []
    for i in range(len(args)):
        if isinstance(args[i], Add):
            for aa in args[i].args:
                tp = TensorProduct(*args[:i] + (aa,) + args[i + 1:])
                if isinstance(tp, TensorProduct):
                    tp = tp._eval_expand_tensorproduct()
                add_args.append(tp)
            break

    if add_args:
        return Add(*add_args)
    else:
        return self

def assemble_toc_fignumbers(self) -> Dict[str, Dict[str, Dict[str, Tuple[int, ...]]]]:
    # Assemble toc_fignumbers to resolve figure numbers on SingleHTML.
    # Merge all fignumbers to single fignumber.
    #
    # Note: current Sphinx has refid confliction in singlehtml mode.
    #       To avoid the problem, it replaces key of secnumbers to
    #       tuple of docname and refid.
    #
    #       There are related codes in inline_all_toctres() and
    #       HTMLTranslter#add_fignumber().
    new_fignumbers = {}  # type: Dict[str, Dict[str, Tuple[int, ...]]]
    # {'foo': {'figure': {'id2': (2,), 'id1': (1,)}}, 'bar': {'figure': {'id1': (3,)}}}
    for docname, fignumlist in self.env.toc_fignumbers.items():
        for figtype, fignums in fignumlist.items():
            alias = "%s/%s" % (docname, figtype)
            new_fignumbers.setdefault(alias, {})
            for id, fignum in fignums.items():
                new_fignumbers[alias][id] = fignum

    return {self.config.master_doc: new_fignumbers}

def resolve_references(self, doctree: nodes.document, fromdocname: str,
                       builder: "Builder") -> None:
    self.apply_post_transforms(doctree, fromdocname)

def run(self) -> Tuple[List[Node], List[system_message]]:
    if ':' not in self.name:
        self.refdomain, self.reftype = '', self.name
        self.classes = ['xref', self.reftype]
    else:
        self.refdomain, self.reftype = self.name.split(':', 1)
        self.classes = ['xref', self.refdomain, '%s-%s' % (self.refdomain, self.reftype)]

    if self.disabled:
        return self.create_non_xref_node()
    else:
        return self.create_xref_node()

def setup(app: "Sphinx") -> Dict[str, Any]:
    from docutils.parsers.rst import roles

    for rolename, nodeclass in generic_docroles.items():
        generic = roles.GenericRole(rolename, nodeclass)
        role = roles.CustomRole(rolename, generic, {'classes': [rolename]})
        roles.register_local_role(rolename, role)

    for rolename, func in specific_docroles.items():
        roles.register_local_role(rolename, func)

    return {
        'version': 'builtin',
        'parallel_read_safe': True,
        'parallel_write_safe': True,
    }

def apply(self, **kwargs: Any) -> None:
    for domain in self.env.domains.values():
        domain.process_doc(self.env, self.env.docname, self.document)

def _print_Pow(self, expr):
    # Treat x**Rational(1,n) as special case
    if expr.exp.is_Rational and abs(expr.exp.p) == 1 and expr.exp.q != 1:
        base = self._print(expr.base)
        expq = expr.exp.q

        if expq == 2:
            tex = r"\sqrt{%s}" % base
        elif self._settings['itex']:
            tex = r"\root{%d}{%s}" % (expq, base)
        else:
            tex = r"\sqrt[%d]{%s}" % (expq, base)

        if expr.exp.is_negative:
            return r"\frac{1}{%s}" % tex
        else:
            return tex
    elif self._settings['fold_frac_powers'] \
        and expr.exp.is_Rational \
            and expr.exp.q != 1:
        base, p, q = self.parenthesize(expr.base, PRECEDENCE['Pow']), expr.exp.p, expr.exp.q
        if expr.base.is_Function:
            return self._print(expr.base, "%s/%s" % (p, q))
        return r"%s^{%s/%s}" % (base, p, q)
    elif expr.exp.is_Rational and expr.exp.is_negative and expr.base.is_commutative:
        # Things like 1/x
        return self._print_Mul(expr)
    else:
        if expr.base.is_Function:
            return self._print(expr.base, self._print(expr.exp))
        else:
            if expr.is_commutative and expr.exp == -1:
                #solves issue 4129
                #As Mul always simplify 1/x to x**-1
                #The objective is achieved with this hack
                #first we get the latex for -1 * expr,
                #which is a Mul expression
                tex = self._print(S.NegativeOne * expr).strip()
                #the result comes with a minus and a space, so we remove
                if tex[:1] == "-":
                    return tex[1:].strip()
            tex = r"%s^{%s}"

            return tex % (self.parenthesize(expr.base, PRECEDENCE['Pow']),
                          self._print(expr.exp))

def _print_Mul(self, expr):
    include_parens = False
    if _coeff_isneg(expr):
        expr = -expr
        tex = "- "
        if expr.is_Add:
            tex += "("
            include_parens = True
    else:
        tex = ""

    from sympy.simplify import fraction
    numer, denom = fraction(expr, exact=True)
    separator = self._settings['mul_symbol_latex']
    numbersep = self._settings['mul_symbol_latex_numbers']

    def convert(expr):
        if not expr.is_Mul:
            return str(self._print(expr))
        else:
            _tex = last_term_tex = ""

            if self.order not in ('old', 'none'):
                args = expr.as_ordered_factors()
            else:
                args = expr.args

            for i, term in enumerate(args):
                term_tex = self._print(term)

                if self._needs_mul_brackets(term, first=(i == 0),
                                            last=(i == len(args) - 1)):
                    term_tex = r"\left(%s\right)" % term_tex

                if _between_two_numbers_p[0].search(last_term_tex) and \
                        _between_two_numbers_p[1].match(term_tex):
                    # between two numbers
                    _tex += numbersep
                elif _tex:
                    _tex += separator

                _tex += term_tex
                last_term_tex = term_tex
            return _tex

    if denom is S.One:
        # use the original expression here, since fraction() may have
        # altered it when producing numer and denom
        tex += convert(expr)
    else:
        snumer = convert(numer)
        sdenom = convert(denom)
        ldenom = len(sdenom.split())
        ratio = self._settings['long_frac_ratio']
        if self._settings['fold_short_frac'] \
                and ldenom <= 2 and not "^" in sdenom:
            # handle short fractions
            if self._needs_mul_brackets(numer, last=False):
                tex += r"\left(%s\right) / %s" % (snumer, sdenom)
            else:
                tex += r"%s / %s" % (snumer, sdenom)
        elif len(snumer.split()) > ratio*ldenom:
            # handle long fractions
            if self._needs_mul_brackets(numer, last=True):
                tex += r"\frac{1}{%s}%s\left(%s\right)" \
                    % (sdenom, separator, snumer)
            elif numer.is_Mul:
                # split a long numerator
                a = S.One
                b = S.One
                for x in numer.args:
                    if self._needs_mul_brackets(x, last=False) or \
                            len(convert(a*x).split()) > ratio*ldenom or \
                            (b.is_commutative is x.is_commutative is False):
                        b *= x
                    else:
                        a *= x
                if self._needs_mul_brackets(b, last=True):
                    tex += r"\frac{%s}{%s}%s\left(%s\right)" \
                        % (convert(a), sdenom, separator, convert(b))
                else:
                    tex += r"\frac{%s}{%s}%s%s" \
                        % (convert(a), sdenom, separator, convert(b))
            else:
                tex += r"\frac{1}{%s}%s%s" % (sdenom, separator, snumer)
        else:
            tex += r"\frac{%s}{%s}" % (snumer, sdenom)

    if include_parens:
        tex += ")"
    return tex

def _print_Mul(self, product):
    a = []  # items in the numerator
    b = []  # items that are in the denominator (if any)

    if self.order not in ('old', 'none'):
        args = product.as_ordered_factors()
    else:
        args = product.args

    # Gather terms for numerator/denominator
    for item in args:
        if item.is_commutative and item.is_Pow and item.exp.is_Rational and item.exp.is_negative:
            if item.exp != -1:
                b.append(Pow(item.base, -item.exp, evaluate=False))
            else:
                b.append(Pow(item.base, -item.exp))
        elif item.is_Rational and item is not S.Infinity:
            if item.p != 1:
                a.append( Rational(item.p) )
            if item.q != 1:
                b.append( Rational(item.q) )
        else:
            a.append(item)

    from sympy import Integral, Piecewise, Product, Sum

    # Convert to pretty forms. Add parens to Add instances if there
    # is more than one term in the numer/denom
    for i in range(0, len(a)):
        if (a[i].is_Add and len(a) > 1) or (i != len(a) - 1 and
                isinstance(a[i], (Integral, Piecewise, Product, Sum))):
            a[i] = prettyForm(*self._print(a[i]).parens())
        elif a[i].is_Relational:
            a[i] = prettyForm(*self._print(a[i]).parens())
        else:
            a[i] = self._print(a[i])

    for i in range(0, len(b)):
        if (b[i].is_Add and len(b) > 1) or (i != len(b) - 1 and
                isinstance(b[i], (Integral, Piecewise, Product, Sum))):
            b[i] = prettyForm(*self._print(b[i]).parens())
        else:
            b[i] = self._print(b[i])

    # Construct a pretty form
    if len(b) == 0:
        return prettyForm.__mul__(*a)
    else:
        if len(a) == 0:
            a.append( self._print(S.One) )
        return prettyForm.__mul__(*a)/prettyForm.__mul__(*b)

def eval_sum(f, limits):
    from sympy.concrete.delta import deltasummation, _has_simple_delta
    from sympy.functions import KroneckerDelta

    (i, a, b) = limits
    if f is S.Zero:
        return S.Zero
    if i not in f.free_symbols:
        return f*(b - a + 1)
    if a == b:
        return f.subs(i, a)
    if isinstance(f, Piecewise):
        if not any(i in arg.args[1].free_symbols for arg in f.args):
            # Piecewise conditions do not depend on the dummy summation variable,
            # therefore we can fold:     Sum(Piecewise((e, c), ...), limits)
            #                        --> Piecewise((Sum(e, limits), c), ...)
            newargs = []
            for arg in f.args:
                newexpr = eval_sum(arg.expr, limits)
                if newexpr is None:
                    return None
                newargs.append((newexpr, arg.cond))
            return f.func(*newargs)

    if f.has(KroneckerDelta) and _has_simple_delta(f, limits[0]):
        return deltasummation(f, limits)

    dif = b - a
    definite = dif.is_Integer
    # Doing it directly may be faster if there are very few terms.
    if definite and (dif < 100):
        return eval_sum_direct(f, (i, a, b))
    if isinstance(f, Piecewise):
        return None
    # Try to do it symbolically. Even when the number of terms is known,
    # this can save time when b-a is big.
    # We should try to transform to partial fractions
    value = eval_sum_symbolic(f.expand(), (i, a, b))
    if value is not None:
        return value
    # Do it directly
    if definite:
        return eval_sum_direct(f, (i, a, b))

def doit(self, **hints):
    if hints.get('deep', True):
        f = self.function.doit(**hints)
    else:
        f = self.function

    if self.function.is_Matrix:
        return self.expand().doit()

    for n, limit in enumerate(self.limits):
        i, a, b = limit
        dif = b - a
        if dif.is_integer and (dif < 0) == True:
            a, b = b + 1, a - 1
            f = -f

        newf = eval_sum(f, (i, a, b))
        if newf is None:
            if f == self.function:
                zeta_function = self.eval_zeta_function(f, (i, a, b))
                if zeta_function is not None:
                    return zeta_function
                return self
            else:
                return self.func(f, *self.limits[n:])
        f = newf

    if hints.get('deep', True):
        # eval_sum could return partially unevaluated
        # result with Piecewise.  In this case we won't
        # doit() recursively.
        if not isinstance(f, Piecewise):
            return f.doit(**hints)

    return f

def eval_sum_symbolic(f, limits):
    from sympy.functions import harmonic, bernoulli

    f_orig = f
    (i, a, b) = limits
    if not f.has(i):
        return f*(b - a + 1)

    # Linearity
    if f.is_Mul:
        L, R = f.as_two_terms()

        if not L.has(i):
            sR = eval_sum_symbolic(R, (i, a, b))
            if sR:
                return L*sR

        if not R.has(i):
            sL = eval_sum_symbolic(L, (i, a, b))
            if sL:
                return R*sL

        try:
            f = apart(f, i)  # see if it becomes an Add
        except PolynomialError:
            pass

    if f.is_Add:
        L, R = f.as_two_terms()
        lrsum = telescopic(L, R, (i, a, b))

        if lrsum:
            return lrsum

        lsum = eval_sum_symbolic(L, (i, a, b))
        rsum = eval_sum_symbolic(R, (i, a, b))

        if None not in (lsum, rsum):
            r = lsum + rsum
            if not r is S.NaN:
                return r

    # Polynomial terms with Faulhaber's formula
    n = Wild('n')
    result = f.match(i**n)

    if result is not None:
        n = result[n]

        if n.is_Integer:
            if n >= 0:
                if (b is S.Infinity and not a is S.NegativeInfinity) or \
                   (a is S.NegativeInfinity and not b is S.Infinity):
                    return S.Infinity
                return ((bernoulli(n + 1, b + 1) - bernoulli(n + 1, a))/(n + 1)).expand()
            elif a.is_Integer and a >= 1:
                if n == -1:
                    return harmonic(b) - harmonic(a - 1)
                else:
                    return harmonic(b, abs(n)) - harmonic(a - 1, abs(n))

    if not (a.has(S.Infinity, S.NegativeInfinity) or
            b.has(S.Infinity, S.NegativeInfinity)):
        # Geometric terms
        c1 = Wild('c1', exclude=[i])
        c2 = Wild('c2', exclude=[i])
        c3 = Wild('c3', exclude=[i])

        e = f.match(c1**(c2*i + c3))

        if e is not None:
            p = (c1**c3).subs(e)
            q = (c1**c2).subs(e)

            r = p*(q**a - q**(b + 1))/(1 - q)
            l = p*(b - a + 1)

            return Piecewise((l, Eq(q, S.One)), (r, True))

        r = gosper_sum(f, (i, a, b))

        if not r in (None, S.NaN):
            return r

    return eval_sum_hyper(f_orig, (i, a, b))

def eval(cls, n, sym=None):
    if n is S.Infinity:
        return S.Infinity

    if n.is_Integer:
        n = int(n)
        if n < 0:
            return S.NegativeOne**(n + 1) * fibonacci(-n)
        if sym is None:
            return Integer(cls._fib(n))
        else:
            if n < 1:
                raise ValueError("Fibonacci polynomials are defined "
                   "only for positive integer indices.")
            return cls._fibpoly(n).subs(_sym, sym)

def eval(cls, n):
    if n is S.Infinity:
        return S.Infinity

    if n.is_Integer:
        return fibonacci(n + 1) + fibonacci(n - 1)

def eval(cls, n, k_sym=None, symbols=None):
    if n.is_Integer and n.is_nonnegative:
        if k_sym is None:
            return Integer(cls._bell(int(n)))
        elif symbols is None:
            return cls._bell_poly(int(n)).subs(_sym, k_sym)
        else:
            r = cls._bell_incomplete_poly(int(n), int(k_sym), symbols)
            return r

def apart(f, x=None, full=False, **options):
    """
    Compute partial fraction decomposition of a rational function.

    Given a rational function ``f``, computes the partial fraction
    decomposition of ``f``. Two algorithms are available: One is based on the
    undertermined coefficients method, the other is Bronstein's full partial
    fraction decomposition algorithm.

    The undetermined coefficients method (selected by ``full=False``) uses
    polynomial factorization (and therefore accepts the same options as
    factor) for the denominator. Per default it works over the rational
    numbers, therefore decomposition of denominators with non-rational roots
    (e.g. irrational, complex roots) is not supported by default (see options
    of factor).

    Bronstein's algorithm can be selected by using ``full=True`` and allows a
    decomposition of denominators with non-rational roots. A human-readable
    result can be obtained via ``doit()`` (see examples below).

    Examples
    ========

    >>> from sympy.polys.partfrac import apart
    >>> from sympy.abc import x, y

    By default, using the undetermined coefficients method:

    >>> apart(y/(x + 2)/(x + 1), x)
    -y/(x + 2) + y/(x + 1)

    The undetermined coefficients method does not provide a result when the
    denominators roots are not rational:

    >>> apart(y/(x**2 + x + 1), x)
    y/(x**2 + x + 1)

    You can choose Bronstein's algorithm by setting ``full=True``:

    >>> apart(y/(x**2 + x + 1), x, full=True)
    RootSum(_w**2 + _w + 1, Lambda(_a, (-2*_a*y/3 - y/3)/(-_a + x)))

    Calling ``doit()`` yields a human-readable result:

    >>> apart(y/(x**2 + x + 1), x, full=True).doit()
    (-y/3 - 2*y*(-1/2 - sqrt(3)*I/2)/3)/(x + 1/2 + sqrt(3)*I/2) + (-y/3 -
        2*y*(-1/2 + sqrt(3)*I/2)/3)/(x + 1/2 - sqrt(3)*I/2)


    See Also
    ========

    apart_list, assemble_partfrac_list
    """
    allowed_flags(options, [])

    f = sympify(f)

    if f.is_Atom:
        return f
    else:
        P, Q = f.as_numer_denom()

    _options = options.copy()
    options = set_defaults(options, extension=True)
    try:
        (P, Q), opt = parallel_poly_from_expr((P, Q), x, **options)
    except PolynomialError as msg:
        if f.is_commutative:
            raise PolynomialError(msg)
        # non-commutative
        if f.is_Mul:
            c, nc = f.args_cnc(split_1=False)
            nc = f.func(*nc)
            if c:
                c = apart(f.func._from_args(c), x=x, full=full, **_options)
                return c*nc
            else:
                return nc
        elif f.is_Add:
            c = []
            nc = []
            for i in f.args:
                if i.is_commutative:
                    c.append(i)
                else:
                    try:
                        nc.append(apart(i, x=x, full=full, **_options))
                    except NotImplementedError:
                        nc.append(i)
            return apart(f.func(*c), x=x, full=full, **_options) + f.func(*nc)
        else:
            reps = []
            pot = preorder_traversal(f)
            next(pot)
            for e in pot:
                try:
                    reps.append((e, apart(e, x=x, full=full, **_options)))
                    pot.skip()  # this was handled successfully
                except NotImplementedError:
                    pass
            return f.xreplace(dict(reps))

    if P.is_multivariate:
        fc = f.cancel()
        if fc != f:
            return apart(fc, x=x, full=full, **_options)

        raise NotImplementedError(
            "multivariate partial fraction decomposition")

    common, P, Q = P.cancel(Q)

    poly, P = P.div(Q, auto=True)
    P, Q = P.rat_clear_denoms(Q)

    if Q.degree() <= 1:
        partial = P/Q
    else:
        if not full:
            partial = apart_undetermined_coeffs(P, Q)
        else:
            partial = apart_full_decomposition(P, Q)

    terms = S.Zero

    for term in Add.make_args(partial):
        if term.has(RootSum):
            terms += term
        else:
            terms += factor(term)

    return common*(poly.as_expr() + terms)

def parallel_poly_from_expr(exprs, *gens, **args):
    """Construct polynomials from expressions. """
    opt = options.build_options(gens, args)
    return _parallel_poly_from_expr(exprs, opt)

def _parallel_poly_from_expr(exprs, opt):
    """Construct polynomials from expressions. """
    from sympy.functions.elementary.piecewise import Piecewise

    if len(exprs) == 2:
        f, g = exprs

        if isinstance(f, Poly) and isinstance(g, Poly):
            f = f.__class__._from_poly(f, opt)
            g = g.__class__._from_poly(g, opt)

            f, g = f.unify(g)

            opt.gens = f.gens
            opt.domain = f.domain

            if opt.polys is None:
                opt.polys = True

            return [f, g], opt

    origs, exprs = list(exprs), []
    _exprs, _polys = [], []

    failed = False

    for i, expr in enumerate(origs):
        expr = sympify(expr)

        if isinstance(expr, Basic):
            if expr.is_Poly:
                _polys.append(i)
            else:
                _exprs.append(i)

                if opt.expand:
                    expr = expr.expand()
        else:
            failed = True

        exprs.append(expr)

    if failed:
        raise PolificationFailed(opt, origs, exprs, True)

    if _polys:
        # XXX: this is a temporary solution
        for i in _polys:
            exprs[i] = exprs[i].as_expr()

    reps, opt = _parallel_dict_from_expr(exprs, opt)
    if not opt.gens:
        raise PolificationFailed(opt, origs, exprs, True)

    for k in opt.gens:
        if isinstance(k, Piecewise):
            raise PolynomialError("Piecewise generators do not make sense")

    coeffs_list, lengths = [], []

    all_monoms = []
    all_coeffs = []

    for rep in reps:
        monoms, coeffs = list(zip(*list(rep.items())))

        coeffs_list.extend(coeffs)
        all_monoms.append(monoms)

        lengths.append(len(coeffs))

    domain = opt.domain

    if domain is None:
        opt.domain, coeffs_list = construct_domain(coeffs_list, opt=opt)
    else:
        coeffs_list = list(map(domain.from_sympy, coeffs_list))

    for k in lengths:
        all_coeffs.append(coeffs_list[:k])
        coeffs_list = coeffs_list[k:]

    polys = []

    for monoms, coeffs in zip(all_monoms, all_coeffs):
        rep = dict(list(zip(monoms, coeffs)))
        poly = Poly._from_dict(rep, opt)
        polys.append(poly)

    if opt.polys is None:
        opt.polys = bool(_polys)

    return polys, opt

def _eval_row_join(self, other):
    cols = self.cols

    def entry(i, j):
        if j < cols:
            return self[i, j]
        return other[i, j - cols]

    return classof(self, other)._new(self.rows, self.cols + other.cols,
                                     lambda i, j: entry(i, j))

def classof(A, B):
    """
    Get the type of the result when combining matrices of different types.

    Currently the strategy is that immutability is contagious.

    Examples
    ========

    >>> from sympy import Matrix, ImmutableMatrix
    >>> from sympy.matrices.matrices import classof
    >>> M = Matrix([[1, 2], [3, 4]]) # a Mutable Matrix
    >>> IM = ImmutableMatrix([[1, 2], [3, 4]])
    >>> classof(M, IM)
    <class 'sympy.matrices.immutable.ImmutableDenseMatrix'>
    """
    try:
        if A._class_priority > B._class_priority:
            return A.__class__
        else:
            return B.__class__
    except Exception:
        pass
    try:
        import numpy
        if isinstance(A, numpy.ndarray):
            return B.__class__
        if isinstance(B, numpy.ndarray):
            return A.__class__
    except Exception:
        pass
    raise TypeError("Incompatible classes %s, %s" % (A.__class__, B.__class__))

def _eval_col_insert(self, pos, other):
    cols = self.cols

    def entry(i, j):
        if j < pos:
            return self[i, j]
        elif pos <= j < pos + other.cols:
            return other[i, j - pos]
        return self[i, j - pos - other.cols]

    return self._new(self.rows, self.cols + other.cols,
                     lambda i, j: entry(i, j))

def __eq__(self, other):
    if isinstance(other, float):
        # coerce to Float at same precision
        o = Float(other)
        try:
            ompf = o._as_mpf_val(self._prec)
        except ValueError:
            return False
        return bool(mlib.mpf_eq(self._mpf_, ompf))
    try:
        other = _sympify(other)
    except SympifyError:
        return NotImplemented
    if isinstance(other, NumberSymbol):
        if other.is_irrational:
            return False
        return other.__eq__(self)
    if isinstance(other, Float):
        return bool(mlib.mpf_eq(self._mpf_, other._mpf_))
    if isinstance(other, Number):
        # numbers should compare at the same precision;
        # all _as_mpf_val routines should be sure to abide
        # by the request to change the prec if necessary; if
        # they don't, the equality test will fail since it compares
        # the mpf tuples
        ompf = other._as_mpf_val(self._prec)
        return bool(mlib.mpf_eq(self._mpf_, ompf))
    return False    # Float != non-Number

def evalf_pow(v, prec, options):

    target_prec = prec
    base, exp = v.args

    # We handle x**n separately. This has two purposes: 1) it is much
    # faster, because we avoid calling evalf on the exponent, and 2) it
    # allows better handling of real/imaginary parts that are exactly zero
    if exp.is_Integer:
        p = exp.p
        # Exact
        if not p:
            return fone, None, prec, None
        # Exponentiation by p magnifies relative error by |p|, so the
        # base must be evaluated with increased precision if p is large
        prec += int(math.log(abs(p), 2))
        re, im, re_acc, im_acc = evalf(base, prec + 5, options)
        # Real to integer power
        if re and not im:
            return mpf_pow_int(re, p, target_prec), None, target_prec, None
        # (x*I)**n = I**n * x**n
        if im and not re:
            z = mpf_pow_int(im, p, target_prec)
            case = p % 4
            if case == 0:
                return z, None, target_prec, None
            if case == 1:
                return None, z, None, target_prec
            if case == 2:
                return mpf_neg(z), None, target_prec, None
            if case == 3:
                return None, mpf_neg(z), None, target_prec
        # Zero raised to an integer power
        if not re:
            return None, None, None, None
        # General complex number to arbitrary integer power
        re, im = libmp.mpc_pow_int((re, im), p, prec)
        # Assumes full accuracy in input
        return finalize_complex(re, im, target_prec)

    # Pure square root
    if exp is S.Half:
        xre, xim, _, _ = evalf(base, prec + 5, options)
        # General complex square root
        if xim:
            re, im = libmp.mpc_sqrt((xre or fzero, xim), prec)
            return finalize_complex(re, im, prec)
        if not xre:
            return None, None, None, None
        # Square root of a negative real number
        if mpf_lt(xre, fzero):
            return None, mpf_sqrt(mpf_neg(xre), prec), None, prec
        # Positive square root
        return mpf_sqrt(xre, prec), None, prec, None

    # We first evaluate the exponent to find its magnitude
    # This determines the working precision that must be used
    prec += 10
    yre, yim, _, _ = evalf(exp, prec, options)
    # Special cases: x**0
    if not (yre or yim):
        return fone, None, prec, None

    ysize = fastlog(yre)
    # Restart if too big
    # XXX: prec + ysize might exceed maxprec
    if ysize > 5:
        prec += ysize
        yre, yim, _, _ = evalf(exp, prec, options)

    # Pure exponential function; no need to evalf the base
    if base is S.Exp1:
        if yim:
            re, im = libmp.mpc_exp((yre or fzero, yim), prec)
            return finalize_complex(re, im, target_prec)
        return mpf_exp(yre, target_prec), None, target_prec, None

    xre, xim, _, _ = evalf(base, prec + 5, options)
    # 0**y
    if not (xre or xim):
        return None, None, None, None

    # (real ** complex) or (complex ** complex)
    if yim:
        re, im = libmp.mpc_pow(
            (xre or fzero, xim or fzero), (yre or fzero, yim),
            target_prec)
        return finalize_complex(re, im, target_prec)
    # complex ** real
    if xim:
        re, im = libmp.mpc_pow_mpf((xre or fzero, xim), yre, target_prec)
        return finalize_complex(re, im, target_prec)
    # negative ** real
    elif mpf_lt(xre, fzero):
        re, im = libmp.mpc_pow_mpf((xre, fzero), yre, target_prec)
        return finalize_complex(re, im, target_prec)
    # positive ** real
    else:
        return mpf_pow(xre, yre, target_prec), None, target_prec, None

def _eval_subs(self, old, new):
    from sympy import exp, log, Symbol
    def _check(ct1, ct2, old):
        """Return (bool, pow, remainder_pow) where, if bool is True, then the
        exponent of Pow `old` will combine with `pow` so the substitution
        is valid, otherwise bool will be False.

        For noncommutative objects, `pow` will be an integer, and a factor
        `Pow(old.base, remainder_pow)` needs to be included. If there is
        no such factor, None is returned. For commutative objects,
        remainder_pow is always None.

        cti are the coefficient and terms of an exponent of self or old
        In this _eval_subs routine a change like (b**(2*x)).subs(b**x, y)
        will give y**2 since (b**x)**2 == b**(2*x); if that equality does
        not hold then the substitution should not occur so `bool` will be
        False.

        """
        coeff1, terms1 = ct1
        coeff2, terms2 = ct2
        if terms1 == terms2:
            if old.is_commutative:
                # Allow fractional powers for commutative objects
                pow = coeff1/coeff2
                try:
                    pow = as_int(pow)
                    combines = True
                except ValueError:
                    combines = Pow._eval_power(
                        Pow(*old.as_base_exp(), evaluate=False),
                        pow) is not None
                return combines, pow, None
            else:
                # With noncommutative symbols, substitute only integer powers
                if not isinstance(terms1, tuple):
                    terms1 = (terms1,)
                if not all(term.is_integer for term in terms1):
                    return False, None, None

                try:
                    # Round pow toward zero
                    pow, remainder = divmod(as_int(coeff1), as_int(coeff2))
                    if pow < 0 and remainder != 0:
                        pow += 1
                        remainder -= as_int(coeff2)

                    if remainder == 0:
                        remainder_pow = None
                    else:
                        remainder_pow = Mul(remainder, *terms1)

                    return True, pow, remainder_pow
                except ValueError:
                    # Can't substitute
                    pass

        return False, None, None

    if old == self.base:
        return new**self.exp._subs(old, new)

    # issue 10829: (4**x - 3*y + 2).subs(2**x, y) -> y**2 - 3*y + 2
    if isinstance(old, self.func) and self.exp == old.exp:
        l = log(self.base, old.base)
        if l.is_Number:
            return Pow(new, l)

    if isinstance(old, self.func) and self.base == old.base:
        if self.exp.is_Add is False:
            ct1 = self.exp.as_independent(Symbol, as_Add=False)
            ct2 = old.exp.as_independent(Symbol, as_Add=False)
            ok, pow, remainder_pow = _check(ct1, ct2, old)
            if ok:
                # issue 5180: (x**(6*y)).subs(x**(3*y),z)->z**2
                result = self.func(new, pow)
                if remainder_pow is not None:
                    result = Mul(result, Pow(old.base, remainder_pow))
                return result
        else:  # b**(6*x+a).subs(b**(3*x), y) -> y**2 * b**a
            # exp(exp(x) + exp(x**2)).subs(exp(exp(x)), w) -> w * exp(exp(x**2))
            oarg = old.exp
            new_l = []
            o_al = []
            ct2 = oarg.as_coeff_mul()
            for a in self.exp.args:
                newa = a._subs(old, new)
                ct1 = newa.as_coeff_mul()
                ok, pow, remainder_pow = _check(ct1, ct2, old)
                if ok:
                    new_l.append(new**pow)
                    if remainder_pow is not None:
                        o_al.append(remainder_pow)
                    continue
                elif not old.is_commutative and not newa.is_integer:
                    # If any term in the exponent is non-integer,
                    # we do not do any substitutions in the noncommutative case
                    return
                o_al.append(newa)
            if new_l:
                expo = Add(*o_al)
                new_l.append(Pow(self.base, expo, evaluate=False) if expo != 1 else self.base)
                return Mul(*new_l)

    if isinstance(old, exp) and self.exp.is_real and self.base.is_positive:
        ct1 = old.args[0].as_independent(Symbol, as_Add=False)
        ct2 = (self.exp*log(self.base)).as_independent(
            Symbol, as_Add=False)
        ok, pow, remainder_pow = _check(ct1, ct2, old)
        if ok:
            result = self.func(new, pow)  # (2**x).subs(exp(x*log(2)), z) -> z
            if remainder_pow is not None:
                result = Mul(result, Pow(old.base, remainder_pow))
            return result

def _eval_subs(self, old, new):
    if not old.is_Add:
        if old is S.Infinity and -old in self.args:
            # foo - oo is foo + (-oo) internally
            return self.xreplace({-old: -new})
        return None

    coeff_self, terms_self = self.as_coeff_Add()
    coeff_old, terms_old = old.as_coeff_Add()

    if coeff_self.is_Rational and coeff_old.is_Rational:
        if terms_self == terms_old:   # (2 + a).subs( 3 + a, y) -> -1 + y
            return self.func(new, coeff_self, -coeff_old)
        if terms_self == -terms_old:  # (2 + a).subs(-3 - a, y) -> -1 - y
            return self.func(-new, coeff_self, coeff_old)

    if coeff_self.is_Rational and coeff_old.is_Rational \
            or coeff_self == coeff_old:
        args_old, args_self = self.func.make_args(
            terms_old), self.func.make_args(terms_self)
        if len(args_old) < len(args_self):  # (a+b+c).subs(b+c,x) -> a+x
            self_set = set(args_self)
            old_set = set(args_old)

            if old_set < self_set:
                ret_set = self_set - old_set
                return self.func(new, coeff_self, -coeff_old,
                           *[s._subs(old, new) for s in ret_set])

            args_old = self.func.make_args(
                -terms_old)     # (a+b+c+d).subs(-b-c,x) -> a-x+d
            old_set = set(args_old)
            if old_set < self_set:
                ret_set = self_set - old_set
                return self.func(-new, coeff_self, coeff_old,
                           *[s._subs(old, new) for s in ret_set])

def _eval_subs(self, old, new):
    from sympy.functions.elementary.complexes import sign
    from sympy.ntheory.factor_ import multiplicity
    from sympy.simplify.powsimp import powdenest
    from sympy.simplify.radsimp import fraction

    if not old.is_Mul:
        return None

    # try keep replacement literal so -2*x doesn't replace 4*x
    if old.args[0].is_Number and old.args[0] < 0:
        if self.args[0].is_Number:
            if self.args[0] < 0:
                return self._subs(-old, -new)
            return None

    def base_exp(a):
        # if I and -1 are in a Mul, they get both end up with
        # a -1 base (see issue 6421); all we want here are the
        # true Pow or exp separated into base and exponent
        from sympy import exp
        if a.is_Pow or isinstance(a, exp):
            return a.as_base_exp()
        return a, S.One

    def breakup(eq):
        """break up powers of eq when treated as a Mul:
               b**(Rational*e) -> b**e, Rational
            commutatives come back as a dictionary {b**e: Rational}
            noncommutatives come back as a list [(b**e, Rational)]
        """

        (c, nc) = (defaultdict(int), list())
        for a in Mul.make_args(eq):
            a = powdenest(a)
            (b, e) = base_exp(a)
            if e is not S.One:
                (co, _) = e.as_coeff_mul()
                b = Pow(b, e/co)
                e = co
            if a.is_commutative:
                c[b] += e
            else:
                nc.append([b, e])
        return (c, nc)

    def rejoin(b, co):
        """
        Put rational back with exponent; in general this is not ok, but
        since we took it from the exponent for analysis, it's ok to put
        it back.
        """

        (b, e) = base_exp(b)
        return Pow(b, e*co)

    def ndiv(a, b):
        """if b divides a in an extractive way (like 1/4 divides 1/2
        but not vice versa, and 2/5 does not divide 1/3) then return
        the integer number of times it divides, else return 0.
        """
        if not b.q % a.q or not a.q % b.q:
            return int(a/b)
        return 0

    # give Muls in the denominator a chance to be changed (see issue 5651)
    # rv will be the default return value
    rv = None
    n, d = fraction(self)
    self2 = self
    if d is not S.One:
        self2 = n._subs(old, new)/d._subs(old, new)
        if not self2.is_Mul:
            return self2._subs(old, new)
        if self2 != self:
            rv = self2

    # Now continue with regular substitution.

    # handle the leading coefficient and use it to decide if anything
    # should even be started; we always know where to find the Rational
    # so it's a quick test

    co_self = self2.args[0]
    co_old = old.args[0]
    co_xmul = None
    if co_old.is_Rational and co_self.is_Rational:
        # if coeffs are the same there will be no updating to do
        # below after breakup() step; so skip (and keep co_xmul=None)
        if co_old != co_self:
            co_xmul = co_self.extract_multiplicatively(co_old)
    elif co_old.is_Rational:
        return rv

    # break self and old into factors

    (c, nc) = breakup(self2)
    (old_c, old_nc) = breakup(old)

    # update the coefficients if we had an extraction
    # e.g. if co_self were 2*(3/35*x)**2 and co_old = 3/5
    # then co_self in c is replaced by (3/5)**2 and co_residual
    # is 2*(1/7)**2

    if co_xmul and co_xmul.is_Rational and abs(co_old) != 1:
        mult = S(multiplicity(abs(co_old), co_self))
        c.pop(co_self)
        if co_old in c:
            c[co_old] += mult
        else:
            c[co_old] = mult
        co_residual = co_self/co_old**mult
    else:
        co_residual = 1

    # do quick tests to see if we can't succeed

    ok = True
    if len(old_nc) > len(nc):
        # more non-commutative terms
        ok = False
    elif len(old_c) > len(c):
        # more commutative terms
        ok = False
    elif set(i[0] for i in old_nc).difference(set(i[0] for i in nc)):
        # unmatched non-commutative bases
        ok = False
    elif set(old_c).difference(set(c)):
        # unmatched commutative terms
        ok = False
    elif any(sign(c[b]) != sign(old_c[b]) for b in old_c):
        # differences in sign
        ok = False
    if not ok:
        return rv

    if not old_c:
        cdid = None
    else:
        rat = []
        for (b, old_e) in old_c.items():
            c_e = c[b]
            rat.append(ndiv(c_e, old_e))
            if not rat[-1]:
                return rv
        cdid = min(rat)

    if not old_nc:
        ncdid = None
        for i in range(len(nc)):
            nc[i] = rejoin(*nc[i])
    else:
        ncdid = 0  # number of nc replacements we did
        take = len(old_nc)  # how much to look at each time
        limit = cdid or S.Infinity  # max number that we can take
        failed = []  # failed terms will need subs if other terms pass
        i = 0
        while limit and i + take <= len(nc):
            hit = False

            # the bases must be equivalent in succession, and
            # the powers must be extractively compatible on the
            # first and last factor but equal in between.

            rat = []
            for j in range(take):
                if nc[i + j][0] != old_nc[j][0]:
                    break
                elif j == 0:
                    rat.append(ndiv(nc[i + j][1], old_nc[j][1]))
                elif j == take - 1:
                    rat.append(ndiv(nc[i + j][1], old_nc[j][1]))
                elif nc[i + j][1] != old_nc[j][1]:
                    break
                else:
                    rat.append(1)
                j += 1
            else:
                ndo = min(rat)
                if ndo:
                    if take == 1:
                        if cdid:
                            ndo = min(cdid, ndo)
                        nc[i] = Pow(new, ndo)*rejoin(nc[i][0],
                                nc[i][1] - ndo*old_nc[0][1])
                    else:
                        ndo = 1

                        # the left residual

                        l = rejoin(nc[i][0], nc[i][1] - ndo*
                                old_nc[0][1])

                        # eliminate all middle terms

                        mid = new

                        # the right residual (which may be the same as the middle if take == 2)

                        ir = i + take - 1
                        r = (nc[ir][0], nc[ir][1] - ndo*
                             old_nc[-1][1])
                        if r[1]:
                            if i + take < len(nc):
                                nc[i:i + take] = [l*mid, r]
                            else:
                                r = rejoin(*r)
                                nc[i:i + take] = [l*mid*r]
                        else:

                            # there was nothing left on the right

                            nc[i:i + take] = [l*mid]

                    limit -= ndo
                    ncdid += ndo
                    hit = True
            if not hit:

                # do the subs on this failing factor

                failed.append(i)
            i += 1
        else:

            if not ncdid:
                return rv

            # although we didn't fail, certain nc terms may have
            # failed so we rebuild them after attempting a partial
            # subs on them

            failed.extend(range(i, len(nc)))
            for i in failed:
                nc[i] = rejoin(*nc[i]).subs(old, new)

    # rebuild the expression

    if cdid is None:
        do = ncdid
    elif ncdid is None:
        do = cdid
    else:
        do = min(ncdid, cdid)

    margs = []
    for b in c:
        if b in old_c:

            # calculate the new exponent

            e = c[b] - old_c[b]*do
            margs.append(rejoin(b, e))
        else:
            margs.append(rejoin(b.subs(old, new), c[b]))
    if cdid and not ncdid:

        # in case we are replacing commutative with non-commutative,
        # we want the new term to come at the front just like the
        # rest of this routine

        margs = [Pow(new, cdid)] + margs
    return co_residual*self2.func(*margs)*self2.func(*nc)

class ComplexInfinity(with_metaclass(Singleton, AtomicExpr)):
    r"""Complex infinity.

    In complex analysis the symbol `\tilde\infty`, called "complex
    infinity", represents a quantity with infinite magnitude, but
    undetermined complex phase.

    ComplexInfinity is a singleton, and can be accessed by
    ``S.ComplexInfinity``, or can be imported as ``zoo``.

    Examples
    ========

    >>> from sympy import zoo, oo
    >>> zoo + 42
    zoo
    >>> 42/zoo
    0
    >>> zoo + zoo
    nan
    >>> zoo*zoo
    zoo

    See Also
    ========

    Infinity
    """

    is_commutative = True
    is_infinite = True
    is_number = True
    is_prime = False
    is_complex = True
    is_real = False

    __slots__ = []

    def __new__(cls):
        return AtomicExpr.__new__(cls)

    def _latex(self, printer):
        return r"\tilde{\infty}"

    @staticmethod
    def __abs__():
        return S.Infinity

    def floor(self):
        return self

    def ceiling(self):
        return self

    @staticmethod
    def __neg__():
        return S.ComplexInfinity

    def _eval_power(self, expt):
        if expt is S.ComplexInfinity:
            return S.NaN

        if isinstance(expt, Number):
            if expt is S.Zero:
                return S.NaN
            else:
                if expt.is_positive:
                    return S.ComplexInfinity
                else:
                    return S.Zero

    def _sage_(self):
        import sage.all as sage
        return sage.UnsignedInfinityRing.gen()

def __new__(cls, b, e, evaluate=None):
    if evaluate is None:
        evaluate = global_evaluate[0]
    from sympy.functions.elementary.exponential import exp_polar

    b = _sympify(b)
    e = _sympify(e)
    if evaluate:
        if e is S.Zero:
            return S.One
        elif e is S.One:
            return b
        # Only perform autosimplification if exponent or base is a Symbol or number
        elif (b.is_Symbol or b.is_number) and (e.is_Symbol or e.is_number) and\
            e.is_integer and _coeff_isneg(b):
            if e.is_even:
                b = -b
            elif e.is_odd:
                return -Pow(-b, e)
        if S.NaN in (b, e):  # XXX S.NaN**x -> S.NaN under assumption that x != 0
            return S.NaN
        elif b is S.One:
            if abs(e).is_infinite:
                return S.NaN
            return S.One
        else:
            # recognize base as E
            if not e.is_Atom and b is not S.Exp1 and not isinstance(b, exp_polar):
                from sympy import numer, denom, log, sign, im, factor_terms
                c, ex = factor_terms(e, sign=False).as_coeff_Mul()
                den = denom(ex)
                if isinstance(den, log) and den.args[0] == b:
                    return S.Exp1**(c*numer(ex))
                elif den.is_Add:
                    s = sign(im(b))
                    if s.is_Number and s and den == \
                            log(-factor_terms(b, sign=False)) + s*S.ImaginaryUnit*S.Pi:
                        return S.Exp1**(c*numer(ex))

            obj = b._eval_power(e)
            if obj is not None:
                return obj
    obj = Expr.__new__(cls, b, e)
    obj = cls._exec_constructor_postprocessors(obj)
    if not isinstance(obj, Pow):
        return obj
    obj.is_commutative = (b.is_commutative and e.is_commutative)
    return obj

def _eval_power(self, other):
    from sympy import Abs, arg, exp, floor, im, log, re, sign
    b, e = self.as_base_exp()
    if b is S.NaN:
        return (b**e)**other  # let __new__ handle it

    s = None
    if other.is_integer:
        s = 1
    elif b.is_polar:  # e.g. exp_polar, besselj, var('p', polar=True)...
        s = 1
    elif e.is_real is not None:
        # helper functions ===========================
        def _half(e):
            """Return True if the exponent has a literal 2 as the
            denominator, else None."""
            if getattr(e, 'q', None) == 2:
                return True
            n, d = e.as_numer_denom()
            if n.is_integer and d == 2:
                return True
        def _n2(e):
            """Return ``e`` evaluated to a Number with 2 significant
            digits, else None."""
            try:
                rv = e.evalf(2, strict=True)
                if rv.is_Number:
                    return rv
            except PrecisionExhausted:
                pass
        # ===================================================
        if e.is_real:
            # we need _half(other) with constant floor or
            # floor(S.Half - e*arg(b)/2/pi) == 0

            # handle -1 as special case
            if e == -1:
                # floor arg. is 1/2 + arg(b)/2/pi
                if _half(other):
                    if b.is_negative is True:
                        return S.NegativeOne**other*Pow(-b, e*other)
                    if b.is_real is False:
                        return Pow(b.conjugate()/Abs(b)**2, other)
            elif e.is_even:
                if b.is_real:
                    b = abs(b)
                if b.is_imaginary:
                    b = abs(im(b))*S.ImaginaryUnit

            if (abs(e) < 1) == True or e == 1:
                s = 1  # floor = 0
            elif b.is_nonnegative:
                s = 1  # floor = 0
            elif re(b).is_nonnegative and (abs(e) < 2) == True:
                s = 1  # floor = 0
            elif fuzzy_not(im(b).is_zero) and abs(e) == 2:
                s = 1  # floor = 0
            elif _half(other):
                s = exp(2*S.Pi*S.ImaginaryUnit*other*floor(
                    S.Half - e*arg(b)/(2*S.Pi)))
                if s.is_real and _n2(sign(s) - s) == 0:
                    s = sign(s)
                else:
                    s = None
        else:
            # e.is_real is False requires:
            #     _half(other) with constant floor or
            #     floor(S.Half - im(e*log(b))/2/pi) == 0
            try:
                s = exp(2*S.ImaginaryUnit*S.Pi*other*
                    floor(S.Half - im(e*log(b))/2/S.Pi))
                # be careful to test that s is -1 or 1 b/c sign(I) == I:
                # so check that s is real
                if s.is_real and _n2(sign(s) - s) == 0:
                    s = sign(s)
                else:
                    s = None
            except PrecisionExhausted:
                s = None

    if s is not None:
        return s*Pow(b, e*other)

def _eval_power(b, e):

    # don't break up NC terms: (A*B)**3 != A**3*B**3, it is A*B*A*B*A*B
    cargs, nc = b.args_cnc(split_1=False)

    if e.is_Integer:
        return Mul(*[Pow(b, e, evaluate=False) for b in cargs]) * \
            Pow(Mul._from_args(nc), e, evaluate=False)
    if e.is_Rational and e.q == 2:
        from sympy.core.power import integer_nthroot
        from sympy.functions.elementary.complexes import sign
        if b.is_imaginary:
            a = b.as_real_imag()[1]
            if a.is_Rational:
                n, d = abs(a/2).as_numer_denom()
                n, t = integer_nthroot(n, 2)
                if t:
                    d, t = integer_nthroot(d, 2)
                    if t:
                        r = sympify(n)/d
                        return _unevaluated_Mul(r**e.p, (1 + sign(a)*S.ImaginaryUnit)**e.p)

    p = Pow(b, e, evaluate=False)

    if e.is_Rational or e.is_Float:
        return p._eval_expand_power_base()

    return p

def _print_Function(self, expr):
    if expr.func.__name__ in self.known_functions:
        cond_mfunc = self.known_functions[expr.func.__name__]
        for cond, mfunc in cond_mfunc:
            if cond(*expr.args):
                return "%s[%s]" % (mfunc, self.stringify(expr.args, ", "))
    return expr.func.__name__ + "[%s]" % self.stringify(expr.args, ", ")

def __init__(self, settings={}):
    """Register function mappings supplied by user"""
    CodePrinter.__init__(self, settings)
    self.known_functions = dict(known_functions)
    userfuncs = settings.get('user_functions', {})
    for k, v in userfuncs.items():
        if not isinstance(v, list):
            userfuncs[k] = [(lambda *x: True, v)]
            self.known_functions.update(userfuncs)

def _print_Function(self, expr):
    if expr.func.__name__ in self.known_functions:
        cond_func = self.known_functions[expr.func.__name__]
        func = None
        if isinstance(cond_func, str):
            func = cond_func
        else:
            for cond, func in cond_func:
                if cond(*expr.args):
                    break
        if func is not None:
            try:
                return func(self, *[self.parenthesize(item, 0) for item in expr.args])
            except TypeError:
                try:
                    return func(*[self.parenthesize(item, 0) for item in expr.args])
                except TypeError:
                    return "%s(%s)" % (func, self.stringify(expr.args, ", "))
    elif hasattr(expr, '_imp_') and isinstance(expr._imp_, Lambda):
        # inlined function
        return self._print(expr._imp_(*expr.args))
    elif expr.is_Function and self._settings.get('allow_unknown_functions', False):
        return '%s(%s)' % (self._print(expr.func), ', '.join(map(self._print, expr.args)))
    else:
        return self._print_not_supported(expr)

class MCodePrinter(CodePrinter):
    """A printer to convert python expressions to
    strings of the Wolfram's Mathematica code
    """
    printmethod = "_mcode"

    _default_settings = {
        'order': None,
        'full_prec': 'auto',
        'precision': 15,
        'user_functions': {},
        'human': True,
        'allow_unknown_functions': False,
    }

    _number_symbols = set()
    _not_supported = set()

    def __init__(self, settings={}):
        """Register function mappings supplied by user"""
        CodePrinter.__init__(self, settings)
        self.known_functions = dict(known_functions)
        userfuncs = settings.get('user_functions', {})
        for k, v in userfuncs.items():
            if not isinstance(v, list):
                userfuncs[k] = [(lambda *x: True, v)]
                self.known_functions.update(userfuncs)

    doprint = StrPrinter.doprint

    def _print_Pow(self, expr):
        PREC = precedence(expr)
        return '%s^%s' % (self.parenthesize(expr.base, PREC),
                          self.parenthesize(expr.exp, PREC))

    def _print_Mul(self, expr):
        PREC = precedence(expr)
        c, nc = expr.args_cnc()
        res = super(MCodePrinter, self)._print_Mul(expr.func(*c))
        if nc:
            res += '*'
            res += '**'.join(self.parenthesize(a, PREC) for a in nc)
        return res

    def _print_Pi(self, expr):
        return 'Pi'

    def _print_Infinity(self, expr):
        return 'Infinity'

    def _print_NegativeInfinity(self, expr):
        return '-Infinity'

    def _print_list(self, expr):
        return '{' + ', '.join(self.doprint(a) for a in expr) + '}'
    _print_tuple = _print_list
    _print_Tuple = _print_list

    def _print_Function(self, expr):
        if expr.func.__name__ in self.known_functions:
            cond_mfunc = self.known_functions[expr.func.__name__]
            for cond, mfunc in cond_mfunc:
                if cond(*expr.args):
                    return "%s[%s]" % (mfunc, self.stringify(expr.args, ", "))
        return expr.func.__name__ + "[%s]" % self.stringify(expr.args, ", ")

    def _print_Integral(self, expr):
        if len(expr.variables) == 1 and not expr.limits[0][1:]:
            args = [expr.args[0], expr.variables[0]]
        else:
            args = expr.args
        return "Hold[Integrate[" + ', '.join(self.doprint(a) for a in args) + "]]"

    def _print_Sum(self, expr):
        return "Hold[Sum[" + ', '.join(self.doprint(a) for a in expr.args) + "]]"

    def _print_Derivative(self, expr):
        dexpr = expr.expr
        dvars = [i[0] if i[1] == 1 else i for i in expr.variable_count]
        return "Hold[D[" + ', '.join(self.doprint(a) for a in [dexpr] + dvars) + "]]"

class MinMaxBase(Expr, LatticeOp):
    def __new__(cls, *args, **assumptions):
        if not args:
            raise ValueError("The Max/Min functions must have arguments.")

        args = (sympify(arg) for arg in args)

        # first standard filter, for cls.zero and cls.identity
        # also reshape Max(a, Max(b, c)) to Max(a, b, c)
        try:
            args = frozenset(cls._new_args_filter(args))
        except ShortCircuit:
            return cls.zero

        if assumptions.pop('evaluate', True):
            # remove redundant args that are easily identified
            args = cls._collapse_arguments(args, **assumptions)

        # find local zeros
        args = cls._find_localzeros(args, **assumptions)

        if not args:
            return cls.identity

        if len(args) == 1:
            return list(args).pop()

        # base creation
        _args = frozenset(args)
        obj = Expr.__new__(cls, _args, **assumptions)
        obj._argset = _args
        return obj

    @classmethod
    def _collapse_arguments(cls, args, **assumptions):
        """Remove redundant args.

        Examples
        ========

        >>> from sympy import Min, Max
        >>> from sympy.abc import a, b, c, d, e

        Any arg in parent that appears in any
        parent-like function in any of the flat args
        of parent can be removed from that sub-arg:

        >>> Min(a, Max(b, Min(a, c, d)))
        Min(a, Max(b, Min(c, d)))

        If the arg of parent appears in an opposite-than parent
        function in any of the flat args of parent that function
        can be replaced with the arg:

        >>> Min(a, Max(b, Min(c, d, Max(a, e))))
        Min(a, Max(b, Min(a, c, d)))

        """
        from sympy.utilities.iterables import ordered
        from sympy.utilities.iterables import sift
        from sympy.simplify.simplify import walk

        if not args:
            return args
        args = list(ordered(args))
        if cls == Min:
            other = Max
        else:
            other = Min

        # find global comparable max of Max and min of Min if a new
        # value is being introduced in these args at position 0 of
        # the ordered args
        if args[0].is_number:
            sifted = mins, maxs = [], []
            for i in args:
                for v in walk(i, Min, Max):
                    if v.args[0].is_comparable:
                        sifted[isinstance(v, Max)].append(v)
            small = Min.identity
            for i in mins:
                v = i.args[0]
                if v.is_number and (v < small) == True:
                    small = v
            big = Max.identity
            for i in maxs:
                v = i.args[0]
                if v.is_number and (v > big) == True:
                    big = v
            # at the point when this function is called from __new__,
            # there may be more than one numeric arg present since
            # local zeros have not been handled yet, so look through
            # more than the first arg
            if cls == Min:
                for i in range(len(args)):
                    if not args[i].is_number:
                        break
                    if (args[i] < small) == True:
                        small = args[i]
            elif cls == Max:
                for i in range(len(args)):
                    if not args[i].is_number:
                        break
                    if (args[i] > big) == True:
                        big = args[i]
            T = None
            if cls == Min:
                if small != Min.identity:
                    other = Max
                    T = small
            elif big != Max.identity:
                other = Min
                T = big
            if T is not None:
                # remove numerical redundancy
                for i in range(len(args)):
                    a = args[i]
                    if isinstance(a, other):
                        a0 = a.args[0]
                        if ((a0 > T) if other == Max else (a0 < T)) == True:
                            args[i] = cls.identity

        # remove redundant symbolic args
        def do(ai, a):
            if not isinstance(ai, (Min, Max)):
                return ai
            cond = a in ai.args
            if not cond:
                return ai.func(*[do(i, a) for i in ai.args],
                    evaluate=False)
            if isinstance(ai, cls):
                return ai.func(*[do(i, a) for i in ai.args if i != a],
                    evaluate=False)
            return a
        for i, a in enumerate(args):
            args[i + 1:] = [do(ai, a) for ai in args[i + 1:]]

        # factor out common elements as for
        # Min(Max(x, y), Max(x, z)) -> Max(x, Min(y, z))
        # and vice versa when swapping Min/Max -- do this only for the
        # easy case where all functions contain something in common;
        # trying to find some optimal subset of args to modify takes
        # too long
        if len(args) > 1:
            common = None
            remove = []
            sets = []
            for i in range(len(args)):
                a = args[i]
                if not isinstance(a, other):
                    continue
                s = set(a.args)
                common = s if common is None else (common & s)
                if not common:
                    break
                sets.append(s)
                remove.append(i)
            if common:
                sets = filter(None, [s - common for s in sets])
                sets = [other(*s, evaluate=False) for s in sets]
                for i in reversed(remove):
                    args.pop(i)
                oargs = [cls(*sets)] if sets else []
                oargs.extend(common)
                args.append(other(*oargs, evaluate=False))

        return args

    @classmethod
    def _new_args_filter(cls, arg_sequence):
        """
        Generator filtering args.

        first standard filter, for cls.zero and cls.identity.
        Also reshape Max(a, Max(b, c)) to Max(a, b, c),
        and check arguments for comparability
        """
        for arg in arg_sequence:

            # pre-filter, checking comparability of arguments
            if not isinstance(arg, Expr) or arg.is_real is False or (
                    arg.is_number and
                    not arg.is_comparable):
                raise ValueError("The argument '%s' is not comparable." % arg)

            if arg == cls.zero:
                raise ShortCircuit(arg)
            elif arg == cls.identity:
                continue
            elif arg.func == cls:
                for x in arg.args:
                    yield x
            else:
                yield arg

    @classmethod
    def _find_localzeros(cls, values, **options):
        """
        Sequentially allocate values to localzeros.

        When a value is identified as being more extreme than another member it
        replaces that member; if this is never true, then the value is simply
        appended to the localzeros.
        """
        localzeros = set()
        for v in values:
            is_newzero = True
            localzeros_ = list(localzeros)
            for z in localzeros_:
                if id(v) == id(z):
                    is_newzero = False
                else:
                    con = cls._is_connected(v, z)
                    if con:
                        is_newzero = False
                        if con is True or con == cls:
                            localzeros.remove(z)
                            localzeros.update([v])
            if is_newzero:
                localzeros.update([v])
        return localzeros

    @classmethod
    def _is_connected(cls, x, y):
        """
        Check if x and y are connected somehow.
        """
        from sympy.core.exprtools import factor_terms
        def hit(v, t, f):
            if not v.is_Relational:
                return t if v else f
        for i in range(2):
            if x == y:
                return True
            r = hit(x >= y, Max, Min)
            if r is not None:
                return r
            r = hit(y <= x, Max, Min)
            if r is not None:
                return r
            r = hit(x <= y, Min, Max)
            if r is not None:
                return r
            r = hit(y >= x, Min, Max)
            if r is not None:
                return r
            # simplification can be expensive, so be conservative
            # in what is attempted
            x = factor_terms(x - y)
            y = S.Zero

        return False

    def _eval_derivative(self, s):
        # f(x).diff(s) -> x.diff(s) * f.fdiff(1)(s)
        i = 0
        l = []
        for a in self.args:
            i += 1
            da = a.diff(s)
            if da is S.Zero:
                continue
            try:
                df = self.fdiff(i)
            except ArgumentIndexError:
                df = Function.fdiff(self, i)
            l.append(df * da)
        return Add(*l)

    def _eval_rewrite_as_Abs(self, *args, **kwargs):
        from sympy.functions.elementary.complexes import Abs
        s = (args[0] + self.func(*args[1:]))/2
        d = abs(args[0] - self.func(*args[1:]))/2
        return (s + d if isinstance(self, Max) else s - d).rewrite(Abs)

    def evalf(self, prec=None, **options):
        return self.func(*[a.evalf(prec, **options) for a in self.args])
    n = evalf

    _eval_is_algebraic = lambda s: _torf(i.is_algebraic for i in s.args)
    _eval_is_antihermitian = lambda s: _torf(i.is_antihermitian for i in s.args)
    _eval_is_commutative = lambda s: _torf(i.is_commutative for i in s.args)
    _eval_is_complex = lambda s: _torf(i.is_complex for i in s.args)
    _eval_is_composite = lambda s: _torf(i.is_composite for i in s.args)
    _eval_is_even = lambda s: _torf(i.is_even for i in s.args)
    _eval_is_finite = lambda s: _torf(i.is_finite for i in s.args)
    _eval_is_hermitian = lambda s: _torf(i.is_hermitian for i in s.args)
    _eval_is_imaginary = lambda s: _torf(i.is_imaginary for i in s.args)
    _eval_is_infinite = lambda s: _torf(i.is_infinite for i in s.args)
    _eval_is_integer = lambda s: _torf(i.is_integer for i in s.args)
    _eval_is_irrational = lambda s: _torf(i.is_irrational for i in s.args)
    _eval_is_negative = lambda s: _torf(i.is_negative for i in s.args)
    _eval_is_noninteger = lambda s: _torf(i.is_noninteger for i in s.args)
    _eval_is_nonnegative = lambda s: _torf(i.is_nonnegative for i in s.args)
    _eval_is_nonpositive = lambda s: _torf(i.is_nonpositive for i in s.args)
    _eval_is_nonzero = lambda s: _torf(i.is_nonzero for i in s.args)
    _eval_is_odd = lambda s: _torf(i.is_odd for i in s.args)
